import React, {useEffect, useRef, useState} from "react";
import {createPortal} from "react-dom";
import styledCom from "styled-components";
import {AuthUser} from "../../models/auth";
import StaffControlApp from "../../staffControl/StaffControlApp";

const Host = styledCom.div({display: "block", width: "100%", minHeight: "calc(100dvh - var(--app-module-navigation-height))"});

interface Props {
    user: AuthUser;
    onSignOut: () => void;
}

const StaffControlWorkspace = ({user, onSignOut}: Props) => {
    const hostRef = useRef<HTMLDivElement>(null);
    const [mountNode, setMountNode] = useState<HTMLDivElement | null>(null);

    useEffect(() => {
        if (!hostRef.current || hostRef.current.shadowRoot) return;
        const shadowRoot = hostRef.current.attachShadow({mode: "open"});
        const stylesheet = document.createElement("link");
        stylesheet.rel = "stylesheet";
        stylesheet.href = `${process.env.PUBLIC_URL || ""}/staff-control.css`;
        const root = document.createElement("div");
        root.className = "staff-control-root";
        shadowRoot.append(stylesheet, root);
        setMountNode(root);
    }, []);

    return (
        <Host ref={hostRef}>
            {mountNode && createPortal(
                <StaffControlApp user={user} onSignOut={onSignOut}/>,
                mountNode,
            )}
        </Host>
    );
};

export default StaffControlWorkspace;
