import {useEffect, useState, type ComponentType, type ReactNode} from "react";
import AssessmentOutlinedIcon from "@mui/icons-material/AssessmentOutlined";
import BadgeOutlinedIcon from "@mui/icons-material/BadgeOutlined";
import CalendarMonthOutlinedIcon from "@mui/icons-material/CalendarMonthOutlined";
import CloseOutlinedIcon from "@mui/icons-material/CloseOutlined";
import DashboardOutlinedIcon from "@mui/icons-material/DashboardOutlined";
import FactCheckOutlinedIcon from "@mui/icons-material/FactCheckOutlined";
import LogoutOutlinedIcon from "@mui/icons-material/LogoutOutlined";
import ManageSearchOutlinedIcon from "@mui/icons-material/ManageSearchOutlined";
import MenuOutlinedIcon from "@mui/icons-material/MenuOutlined";
import NotificationsNoneOutlinedIcon from "@mui/icons-material/NotificationsNoneOutlined";
import PaymentsOutlinedIcon from "@mui/icons-material/PaymentsOutlined";
import type {SvgIconProps} from "@mui/material/SvgIcon";
import {settingsStore} from "../api/client";
import {AuthUser} from "../../models/auth";
import AppearancePicker from "../../ui/appearance/AppearancePicker";
import Image from "../../ui/images/logo-no-background.png";

export type RouteKey = "dashboard" | "employees" | "schedules" | "attendance" | "payroll" | "reports" | "notifications" | "audit";

type NavigationItem = {
  key: RouteKey;
  label: string;
  icon: ComponentType<SvgIconProps>;
  section?: string;
};

const navigation: NavigationItem[] = [
  {key: "dashboard", label: "Обзор", icon: DashboardOutlinedIcon},
  {key: "employees", label: "Сотрудники", icon: BadgeOutlinedIcon, section: "Рабочее пространство"},
  {key: "schedules", label: "Графики", icon: CalendarMonthOutlinedIcon},
  {key: "attendance", label: "Табель", icon: FactCheckOutlinedIcon},
  {key: "payroll", label: "Зарплата", icon: PaymentsOutlinedIcon, section: "Финансы и контроль"},
  {key: "reports", label: "Аналитика", icon: AssessmentOutlinedIcon},
  {key: "notifications", label: "Уведомления", icon: NotificationsNoneOutlinedIcon},
  {key: "audit", label: "Аудит", icon: ManageSearchOutlinedIcon, section: "Система"},
];

const mobileMediaQuery = "(max-width: 900px)";

export function AppShell({route, onNavigate, user, onSignOut, children}: { route: RouteKey; onNavigate: (route: RouteKey) => void; user: AuthUser; onSignOut: () => void; children: ReactNode }) {
  const [isMobile, setIsMobile] = useState(() => window.matchMedia(mobileMediaQuery).matches);
  const [sidebarOpen, setSidebarOpen] = useState(() => !window.matchMedia(mobileMediaQuery).matches);
  const [hasToken, setHasToken] = useState(Boolean(settingsStore.load().accessToken));

  useEffect(() => {
    const listener = () => setHasToken(Boolean(settingsStore.load().accessToken));
    window.addEventListener("staffcontrol:settings", listener);
    return () => window.removeEventListener("staffcontrol:settings", listener);
  }, []);

  useEffect(() => {
    const media = window.matchMedia(mobileMediaQuery);
    const listener = (event: MediaQueryListEvent) => {
      setIsMobile(event.matches);
      setSidebarOpen(!event.matches);
    };
    media.addEventListener("change", listener);
    return () => media.removeEventListener("change", listener);
  }, []);

  useEffect(() => {
    if (!isMobile || !sidebarOpen) return;
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") setSidebarOpen(false);
    };
    document.addEventListener("keydown", closeOnEscape);
    return () => document.removeEventListener("keydown", closeOnEscape);
  }, [isMobile, sidebarOpen]);

  const navigate = (key: RouteKey) => {
    onNavigate(key);
    if (isMobile) setSidebarOpen(false);
  };
  const settings = settingsStore.load();
  const initials = user.name.split(" ").slice(0, 2).map((part) => part[0]).join("").toUpperCase();

  return (
    <div className={`app-shell ${sidebarOpen ? "sidebar-expanded" : "sidebar-collapsed"}`}>
      <header className="topbar">
        <div className="topbar-brand">
          <img className="topbar-logo" src={Image} alt="VivoTech CRM"/>
          <div className="topbar-product">
            <strong>VivoTech CRM</strong>
            <span>{user.firmName || "Управление персоналом"}</span>
          </div>
          <button
            type="button"
            className="icon-button menu-button"
            aria-label={sidebarOpen ? "Свернуть меню" : "Развернуть меню"}
            title={sidebarOpen ? "Свернуть меню" : "Развернуть меню"}
            aria-expanded={sidebarOpen}
            aria-controls="staff-sidebar"
            onClick={() => setSidebarOpen((value) => !value)}
          >
            {sidebarOpen ? <CloseOutlinedIcon/> : <MenuOutlinedIcon/>}
          </button>
        </div>

        <div className="topbar-actions">
          <AppearancePicker native/>
          <div className="topbar-user">
            <span className="user-avatar">{initials || "CRM"}</span>
            <div><strong>{user.name}</strong><small>{hasToken ? "Защищённая сессия" : "Режим разработки"}</small></div>
          </div>
          <button type="button" className="icon-button signout-button" aria-label="Выйти" title="Выйти" onClick={onSignOut}>
            <LogoutOutlinedIcon/>
          </button>
        </div>
      </header>

      <div className="app-frame">
        <aside id="staff-sidebar" className={`sidebar ${sidebarOpen ? "sidebar-open" : ""}`} aria-hidden={isMobile && !sidebarOpen}>
          <div className="sidebar-title">{sidebarOpen ? "Меню" : "—"}</div>
          <nav aria-label="Основная навигация">
            {navigation.map((item) => {
              const Icon = item.icon;
              return (
                <div key={item.key}>
                  {item.section && <div className="nav-section">{item.section}</div>}
                  <button
                    type="button"
                    className={route === item.key ? "active" : ""}
                    aria-current={route === item.key ? "page" : undefined}
                    aria-label={item.label}
                    title={!sidebarOpen ? item.label : undefined}
                    onClick={() => navigate(item.key)}
                  >
                    <span className="nav-icon"><Icon/></span><span className="nav-label">{item.label}</span>
                  </button>
                </div>
              );
            })}
          </nav>
          <div className="sidebar-footer">
            <div className={`connection-dot ${hasToken ? "secure" : "development"}`}/>
            <div><strong>{hasToken ? "CRM подключён" : "Режим разработки"}</strong><span>{user.firmName || settings.developmentUser}</span></div>
          </div>
        </aside>

        {isMobile && sidebarOpen && <button className="sidebar-scrim" onClick={() => setSidebarOpen(false)} aria-label="Закрыть меню"/>}
        <main className="app-main">
          <nav className="page-breadcrumbs" aria-label="Навигация по странице">
            {route === "dashboard" ? <span aria-current="page">Персонал</span> : <>
              <button type="button" onClick={() => navigate("dashboard")}>Персонал</button>
              <span aria-hidden="true">›</span>
              <span aria-current="page">{navigation.find(item => item.key === route)?.label}</span>
            </>}
          </nav>
          {children}
        </main>
      </div>
    </div>
  );
}
