import {useEffect,useState} from "react";
import {apiRequest,errorMessage} from "../api/client";
import {Alert,Button,EmptyState,Loading,Panel,formatDate,formatDateTime,minutesToHours} from "./ui";
import type {PagedResponse} from "../types";
interface Change {id:string;workDate:string;timestamp:string;actorUserId:string;oldValues?:string;newValues?:string;reason?:string}
function hours(value?:string):string {
  try {const data=JSON.parse(value || "{}");return minutesToHours(data.ActualMinutes ?? data.actualMinutes ?? null);} catch {return "—";}
}
export function ManualChanges({employeeId,revision}:{employeeId:string;revision:number}) {
  const [page,setPage]=useState(1),[data,setData]=useState<PagedResponse<Change>|null>(null),[loading,setLoading]=useState(false),[error,setError]=useState("");
  useEffect(()=>{let active=true;setLoading(true);setError("");
    apiRequest<PagedResponse<Change>>(`/api/employees/${employeeId}/manual-changes?page=${page}`).then(result=>{if(active)setData(result);}).catch(e=>{if(active)setError(errorMessage(e));}).finally(()=>{if(active)setLoading(false);});
    return ()=>{active=false;};
  },[employeeId,page,revision]);
  return <Panel title="Ручные исправления" description="Вся история изменений часов выбранного сотрудника, включая повторные исправления одной даты.">
    {error && <Alert tone="error">{error}</Alert>}
    {loading ? <Loading /> : !data?.items?.length ? <EmptyState title="Ручных исправлений нет" description="Изменения фактических часов появятся здесь с причиной и автором." /> : <>
      <div className="table-wrap"><table><thead><tr><th>Дата табеля</th><th>Было</th><th>Стало</th><th>Причина</th><th>Кто изменил</th><th>Когда</th></tr></thead><tbody>{data.items.map(item=><tr key={item.id}><td><strong>{formatDate(item.workDate)}</strong></td><td>{hours(item.oldValues)}</td><td className="manual-source">{hours(item.newValues)}</td><td>{item.reason || "—"}</td><td>{item.actorUserId}</td><td>{formatDateTime(item.timestamp)}</td></tr>)}</tbody></table></div>
      {data.totalPages>1 && <div className="form-actions"><Button variant="ghost" disabled={page===1} onClick={()=>setPage(page-1)}>Назад</Button><span>{page} / {data.totalPages}</span><Button variant="ghost" disabled={page>=data.totalPages} onClick={()=>setPage(page+1)}>Далее</Button></div>}
    </>}
  </Panel>;
}
