import {PayCalculationModal} from "../components/PayCalculationModal";
import {ManualChanges} from "../components/ManualChanges";
import {useLiveRefresh} from "../hooks/useLiveRefresh";
import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent } from "react";
import { apiRequest, errorMessage, jsonBody, queryString } from "../api/client";
import { Alert, Badge, Button, EmployeeSelect, EmptyState, Field, Input, Loading, Modal, PageHeader, Panel, Select, formatDate, minutesToHours, monthBounds, today } from "../components/ui";
import { useEmployees } from "../hooks/useEmployees";
import type { CalendarDay, EmployeeCalendar, EmployeeTimesheetReport, GenerateTimesheetResult, TimesheetPeriodListItem } from "../types";

const attendanceLabels: Record<string, string> = {
  Planned: "План", Work: "Отработано", MissingSchedule: "Нет графика", DayOff: "Выходной", Holiday: "Праздник",
  ExcusedAbsence: "Уважительная", PartialExcusedAbsence: "Частичное отсутствие", Vacation: "Отпуск", SickLeave: "Больничный",
  UnpaidLeave: "Неоплачиваемый отпуск", PaidLeave: "Оплачиваемый отпуск", BusinessTrip: "Командировка",
  UnexcusedAbsence: "Прогул", OtherAbsence: "Другое отсутствие",
};

const periodStatusLabels: Record<TimesheetPeriodListItem["status"], string> = {
  Open: "Открыт",
  Submitted: "На согласовании",
  Approved: "Согласован",
  Locked: "Закрыт",
};

const sourceLabels: Record<string, string> = {
  Schedule: "График",
  AutoFromSchedule: "Автоматически",
  Manual: "Вручную",
  Absence: "Отсутствие",
  ScheduleOverride: "Исключение из графика",
  OrganizationDayOff: "Общий выходной",
};

function formatShift(start?: string | null, end?: string | null, crossesMidnight?: boolean): string {
  if (!start || !end) return "—";
  return `${start.slice(0, 5)}–${end.slice(0, 5)}${crossesMidnight ? " +1" : ""}`;
}

const approvalSteps = [
  { status: "Open", label: "Сформирован" },
  { status: "Submitted", label: "Отправлен" },
  { status: "Approved", label: "Согласован" },
  { status: "Locked", label: "Закрыт" },
] as const;

function currentMonth(): string {
  const date = new Date();
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
}

function boundsForMonth(value: string): { from: string; to: string } {
  const [year, month] = value.split("-").map(Number);
  return {
    from: `${value}-01`,
    to: `${year}-${String(month).padStart(2, "0")}-${String(new Date(year, month, 0).getDate()).padStart(2, "0")}`,
  };
}

function inclusiveDays(from: string, to: string): number {
  if (!from || !to || from > to) return 0;
  return Math.floor((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000) + 1;
}

export function AttendancePage() {
  const { employees, error: employeeError } = useEmployees();
  const [employeeId, setEmployeeId] = useState("");
  const [month, setMonth] = useState(currentMonth());
  const [calendar, setCalendar] = useState<EmployeeCalendar | null>(null);
  const [selectedDay, setSelectedDay] = useState<CalendarDay | null>(null);
  const [loading, setLoading] = useState(false);
  const [periodLoading, setPeriodLoading] = useState(false);
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [generationResult, setGenerationResult] = useState<GenerateTimesheetResult | null>(null);
  const [timesheet, setTimesheet] = useState<EmployeeTimesheetReport | null>(null);
  const [timesheetLoading, setTimesheetLoading] = useState(false);
  const initialBounds = monthBounds();
  const [dateFrom, setDateFrom] = useState(initialBounds.from);
  const [dateTo, setDateTo] = useState(initialBounds.to);
  const [periods, setPeriods] = useState<TimesheetPeriodListItem[]>([]);
  const [periodId, setPeriodId] = useState("");
  const [showCalculation,setShowCalculation]=useState(false);
  const [changesRevision,setChangesRevision]=useState(0);
  const [showAbsence, setShowAbsence] = useState(false);
  const [absenceType, setAbsenceType] = useState("2");
  const [absencePayTreatment, setAbsencePayTreatment] = useState("1");
  const absenceMustBeUnpaid = absenceType === "4" || absenceType === "7";
  const [showReopen, setShowReopen] = useState(false);
  const timesheetSectionRef = useRef<HTMLDivElement>(null);

  const selectionRef = useRef({employeeId, month, dateFrom, dateTo});
  selectionRef.current = {employeeId, month, dateFrom, dateTo};
  const selectedEmployee = useMemo(
    () => employees.find((employee) => employee.id === employeeId) ?? null,
    [employeeId, employees],
  );
  const selectedPeriod = useMemo(
    () => periods.find((period) => period.id === periodId) ?? periods[0] ?? null,
    [periodId, periods],
  );
  const selectedRangeDays = inclusiveDays(dateFrom, dateTo);
  const rangeIsValid = selectedRangeDays > 0 && selectedRangeDays <= 366;

  const loadCalendar = useCallback(async () => {
    if (!employeeId) { setCalendar(null); return; }
    setLoading(true); setError("");
    try {
      const [year, monthNumber] = month.split("-").map(Number);
      const query = queryString({ year, month: monthNumber });
      const data = await apiRequest<EmployeeCalendar>(`/api/employees/${employeeId}/calendar?${query}`);
      if (selectionRef.current.employeeId === employeeId && selectionRef.current.month === month) setCalendar(data);
    } catch (requestError) { setError(errorMessage(requestError)); } finally { setLoading(false); }
  }, [employeeId, month]);

  const loadPeriods = useCallback(async () => {
    if (!dateFrom || !dateTo || dateFrom > dateTo || inclusiveDays(dateFrom, dateTo) > 366) { setPeriods([]); setPeriodId(""); return; }
    setPeriodLoading(true);
    try {
      const query = queryString({ dateFrom, dateTo });
      const items = await apiRequest<TimesheetPeriodListItem[]>(`/api/timesheet-periods?${query}`);
      if (selectionRef.current.dateFrom !== dateFrom || selectionRef.current.dateTo !== dateTo) return;
      setPeriods(items);
      setPeriodId((current) => items.some((period) => period.id === current) ? current : items[0]?.id ?? "");
    } catch (requestError) { setError(errorMessage(requestError)); } finally { setPeriodLoading(false); }
  }, [dateFrom, dateTo]);

  const loadTimesheet = useCallback(async () => {
    if (!employeeId || !dateFrom || !dateTo || dateFrom > dateTo || inclusiveDays(dateFrom, dateTo) > 366) {
      setTimesheet(null);
      return;
    }

    setTimesheetLoading(true);
    try {
      const query = queryString({ dateFrom, dateTo });
      const data = await apiRequest<EmployeeTimesheetReport>(`/api/employees/${employeeId}/timesheet?${query}`);
      if (selectionRef.current.employeeId === employeeId && selectionRef.current.dateFrom === dateFrom && selectionRef.current.dateTo === dateTo) setTimesheet(data);
    } catch (requestError) {
      setTimesheet(null);
      setError(errorMessage(requestError));
    } finally {
      setTimesheetLoading(false);
    }
  }, [dateFrom, dateTo, employeeId]);

  const refreshLive = useCallback(() => Promise.all([loadCalendar(), loadPeriods(), loadTimesheet()]), [loadCalendar, loadPeriods, loadTimesheet]);
  useLiveRefresh(refreshLive);
  useEffect(() => { void loadCalendar(); }, [loadCalendar]);
  useEffect(() => { void loadPeriods(); }, [loadPeriods]);
  useEffect(() => { void loadTimesheet(); }, [loadTimesheet]);
  useEffect(() => {
    const bounds = boundsForMonth(month);
    setDateFrom(bounds.from);
    setDateTo(bounds.to);
    setGenerationResult(null);
  }, [month]);

  const calendarCells = useMemo(() => {
    if (!calendar?.days.length) return [];
    const first = new Date(`${calendar.days[0]?.date ?? ""}T00:00:00`).getDay();
    const mondayOffset = first === 0 ? 6 : first - 1;
    const cells = [...Array.from({ length: mondayOffset }, () => null), ...calendar.days];
    while (cells.length % 7 !== 0) cells.push(null);
    return cells;
  }, [calendar]);

  const calendarWeeks = Array.from({length:calendarCells.length / 7}, (_,index)=>calendarCells.slice(index*7,index*7+7));
  const todayDate=today();

  const generate = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!employeeId || !rangeIsValid) return;
    const data = new FormData(event.currentTarget);
    const previewOnly = data.get("preview") === "on";
    setBusy("generate"); setError(""); setNotice("");
    try {
      const result = await apiRequest<GenerateTimesheetResult>(`/api/employees/${employeeId}/timesheet/generate`, {
        method: "POST",
        ...jsonBody({ dateFrom, dateTo, previewOnly, forceRecalculateAutoEntries: data.get("force") === "on" }),
      });
      setGenerationResult(result);
      await Promise.all([loadCalendar(), loadPeriods(), loadTimesheet()]);
      window.requestAnimationFrame(() => timesheetSectionRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }));
      if (result.errors > 0) {
        setError(`Табель сформирован частично: не удалось обработать ${result.errors} ${result.errors === 1 ? "строку" : "строк"}. Проверьте строки и назначенный график.`);
      } else {
        setNotice(previewOnly
          ? "Проверка завершена. Данные не изменялись."
          : `Табель сотрудника ${selectedEmployee?.displayName ?? ""} сформирован и показан ниже.`);
      }
    } catch (requestError) { setError(errorMessage(requestError)); } finally { setBusy(""); }
  };

  const adjustDay = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!selectedDay || !employeeId) return;
    const data = new FormData(event.currentTarget); setBusy("adjust"); setError("");
    const actualMinutes = Math.round(Number(data.get("actualHours")) * 60);
    const overtimeMinutes = Math.round(Number(data.get("overtimeHours")) * 60);
    if (!Number.isFinite(actualMinutes) || !Number.isFinite(overtimeMinutes) || actualMinutes < 0 || actualMinutes > 2880 || overtimeMinutes < 0 || overtimeMinutes > actualMinutes) {
      setError("Фактическое время должно быть от 0 до 48 часов; сверхурочное время не может превышать фактическое."); setBusy(""); return;
    }
    try {
      const response = await apiRequest<{ message?: string }>(`/api/employees/${employeeId}/timesheet/${selectedDay.date}`, { method: "PATCH", ...jsonBody({ actualMinutes, overtimeMinutes, comment: data.get("comment") || null, reason: data.get("reason") }) });
      setChangesRevision(value=>value+1); setSelectedDay(null); setNotice(response.message || "Фактическое время и причина изменения сохранены."); await Promise.all([loadCalendar(), loadTimesheet()]);
    } catch (requestError) { setError(errorMessage(requestError)); } finally { setBusy(""); }
  };

  const createAbsence = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const data = new FormData(event.currentTarget); setBusy("absence"); setError("");
    try {
      await apiRequest("/api/absences", { method: "POST", ...jsonBody({ employeeId, dateFrom: data.get("dateFrom"), dateTo: data.get("dateTo"), durationMinutes: data.get("durationMinutes") ? Number(data.get("durationMinutes")) : null, type: Number(absenceType), payTreatment: Number(absencePayTreatment), paymentPercent: absencePayTreatment === "4" ? Number(data.get("paymentPercent")) : null, reason: data.get("reason") }) });
      setShowAbsence(false); setNotice("Отсутствие зарегистрировано."); await Promise.all([loadCalendar(), loadTimesheet()]);
    } catch (requestError) { setError(errorMessage(requestError)); } finally { setBusy(""); }
  };

  const createPeriod = async () => {
    if (!rangeIsValid) return;
    setBusy("period"); setError(""); setNotice("");
    try {
      const response = await apiRequest<{ id: string }>("/api/timesheet-periods", { method: "POST", ...jsonBody({ dateFrom, dateTo }) });
      setPeriodId(response.id);
      setNotice("Период создан. Теперь его можно отправить на согласование.");
      await loadPeriods();
    } catch (requestError) { setError(errorMessage(requestError)); } finally { setBusy(""); }
  };

  const periodAction = async (action: "submit" | "approve" | "lock") => {
    if (!selectedPeriod) return;
    const messages = {
      submit: "Период отправлен на согласование.",
      approve: "Период согласован.",
      lock: "Период закрыт от изменений.",
    };
    setBusy(action); setError(""); setNotice("");
    try {
      await apiRequest(`/api/timesheet-periods/${selectedPeriod.id}/${action}`, { method: "POST" });
      setNotice(messages[action]);
      await loadPeriods();
    } catch (requestError) { setError(errorMessage(requestError)); } finally { setBusy(""); }
  };

  const reopenPeriod = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!selectedPeriod) return;
    const data = new FormData(event.currentTarget);
    setBusy("reopen"); setError(""); setNotice("");
    try {
      await apiRequest(`/api/timesheet-periods/${selectedPeriod.id}/reopen`, {
        method: "POST",
        ...jsonBody({ reason: data.get("reason") }),
      });
      setShowReopen(false);
      setNotice("Период снова открыт для исправлений.");
      await loadPeriods();
    } catch (requestError) { setError(errorMessage(requestError)); } finally { setBusy(""); }
  };

  const monthLabel = new Intl.DateTimeFormat("ru-RU", { month: "long", year: "numeric" }).format(new Date(`${month}-01T00:00:00`));
  const currentStepIndex = selectedPeriod
    ? approvalSteps.findIndex((step) => step.status === selectedPeriod.status)
    : -1;

  return (
    <>
      <PageHeader eyebrow="Рабочее время" title="Табель" description="Выберите сотрудника и месяц — система подставит график, часы и проведёт табель до согласования." actions={<div className="form-actions"><Button disabled={!employeeId} onClick={() => setShowCalculation(true)}>Рассчитать период</Button><Button variant="secondary" disabled={!employeeId} onClick={() => setShowAbsence(true)}>+ Добавить отсутствие</Button></div>} />
      {(error || employeeError) && <Alert tone="error">{error || employeeError}</Alert>}
      {notice && <Alert tone="success" onClose={() => setNotice("")}>{notice}</Alert>}

      <Panel className="calendar-panel">
        <div className="calendar-toolbar">
          <Field label="Сотрудник"><EmployeeSelect employees={employees} value={employeeId} onChange={(value) => { setEmployeeId(value); setGenerationResult(null); setTimesheet(null); }} /></Field>
          <div className="month-picker"><button type="button" onClick={() => { const date = new Date(`${month}-01`); date.setMonth(date.getMonth() - 1); setMonth(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`); }}>←</button><strong>{monthLabel}</strong><button type="button" onClick={() => { const date = new Date(`${month}-01`); date.setMonth(date.getMonth() + 1); setMonth(`${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`); }}>→</button></div>
          <Input type="month" value={month} onChange={(event) => setMonth(event.target.value)} aria-label="Месяц" />
        </div>
        {!employeeId ? <div className="calendar-placeholder"><span>1</span><h3>Сначала выберите сотрудника</h3><p>Покажем его рабочие дни, часы, отсутствия и ручные изменения.</p></div> : loading ? <Loading label="Загружаем табель" /> : (
          <div className="calendar-scroll"><div className="calendar-grid calendar-with-totals">
            {["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс", "Итог недели"].map(day=><div className="weekday" key={day}>{day}</div>)}
            {calendarWeeks.map((week,weekIndex)=><div className="calendar-week" key={weekIndex}>
              {week.map((day,index)=>day === null ? <div className="calendar-day muted" key={index} /> : <button type="button"
                className={`calendar-day ${day.isToday ? "today" : ""} ${day.date < todayDate ? "past" : ""} ${day.isWorkingDay ? "working" : "off"} ${day.periodStatus && day.periodStatus !== "Open" ? "locked" : ""}`}
                key={day.date} onClick={()=>setSelectedDay(day)} title={day.changeReason || day.absenceReason || undefined}>
                <span className="day-number">{Number(day.date.slice(-2))}</span>
                <span className="day-status">{attendanceLabels[day.attendanceStatus] ?? day.attendanceStatus}</span>
                <span className="day-plan">План {minutesToHours(day.plannedMinutes)}</span>
                <strong>Факт {minutesToHours(day.date > todayDate ? 0 : day.actualMinutes ?? 0)}</strong>
                {day.source === "ScheduleOverride" && day.changeReason && <small className="day-reason" title={day.changeReason}>{day.changeReason}</small>}
                {day.isManualOverride && <small className="manual-mark">Вручную</small>}
                {day.warningCodes.some(code=>code !== "attendance.entry_not_generated" || day.date <= todayDate) && <i title={day.warningCodes.join(", ")}>!</i>}
              </button>)}
              {(() => {
                const completed=week.filter((day):day is CalendarDay=>day !== null && (day.date < todayDate || (day.date === todayDate && day.actualMinutes != null)));
                const overtime=completed.reduce((sum,day)=>sum+Math.max(day.overtimeMinutes, (day.actualMinutes ?? 0)-day.plannedMinutes,0),0);
                const under=completed.reduce((sum,day)=>sum+Math.max(day.plannedMinutes-(day.actualMinutes ?? 0),0),0);
                return <div className="week-summary"><span>За неделю</span><strong>{minutesToHours(completed.reduce((sum,day)=>sum+(day.actualMinutes ?? 0),0))}</strong>{overtime>0 && <span className="week-label overtime">Переработка +{minutesToHours(overtime)}</span>}{under>0 && <span className="week-label underwork">Недоработка −{minutesToHours(under)}</span>}{completed.length>0 && overtime===0 && under===0 && <span className="week-label balanced">По плану</span>}</div>;
              })()}
            </div>)}
          </div></div>
        )}
        <div className="calendar-legend"><span><i className="legend-plan" />План</span><span><i className="legend-fact" />Факт</span><span><i className="legend-warning" />Требует внимания</span></div>
      </Panel>

      <div className="two-column align-start attendance-actions">
        <Panel title="1. Сформировать табель" description="Для выбранного сотрудника и периода. Ручные значения и закрытые периоды останутся без изменений.">
          <div className={`selection-summary ${selectedEmployee ? "ready" : ""}`}>
            <span>1</span>
            <div><strong>{selectedEmployee?.displayName ?? "Сотрудник не выбран"}</strong><small>{selectedEmployee ? `${formatDate(dateFrom)} — ${formatDate(dateTo)}` : "Выберите сотрудника в календаре выше"}</small></div>
          </div>
          <form className="stack-form" onSubmit={generate}>
            <div className="form-grid"><Field label="Начало периода"><Input type="date" value={dateFrom} onChange={(event) => setDateFrom(event.target.value)} required /></Field><Field label="Конец периода"><Input type="date" value={dateTo} onChange={(event) => setDateTo(event.target.value)} required /></Field></div>
            {!rangeIsValid && <Alert tone="warning">{dateFrom && dateTo && dateFrom <= dateTo ? "Период не может быть длиннее 366 дней." : "Дата окончания должна быть не раньше даты начала."}</Alert>}
            <details className="advanced-options">
              <summary>Дополнительные настройки</summary>
              <div>
                <label className="check-row"><input name="force" type="checkbox" defaultChecked /> Обновить автоматические часы из графика</label>
                <label className="check-row"><input name="preview" type="checkbox" /> Только проверить, ничего не сохранять</label>
              </div>
            </details>
            <Button type="submit" disabled={!employeeId || !rangeIsValid} busy={busy === "generate"}>Сформировать табель</Button>
          </form>
          {generationResult && <div className="result-grid generation-results"><div><strong>{generationResult.created}</strong><span>дней создано</span></div><div><strong>{generationResult.updated}</strong><span>обновлено</span></div><div><strong>{generationResult.skippedManual}</strong><span>ручных сохранено</span></div><div><strong>{(generationResult.skippedLocked ?? 0) + (generationResult.skippedNonEditable ?? 0)}</strong><span>закрытых сохранено</span></div><div><strong>{generationResult.missingSchedule}</strong><span>без графика</span></div><div className={generationResult.errors > 0 ? "has-error" : ""}><strong>{generationResult.errors}</strong><span>ошибок</span></div></div>}
        </Panel>

        <Panel title="2. Согласовать период" description="Технический ID больше не нужен: выберите период и нажмите доступное следующее действие.">
          {periodLoading ? <Loading label="Ищем периоды за выбранные даты" /> : periods.length === 0 ? (
            <div className="period-empty">
              <span>2</span>
              <h3>Период ещё не создан</h3>
              <p>Сначала сформируйте табель или создайте пустой период за даты {formatDate(dateFrom)} — {formatDate(dateTo)}.</p>
              <Button variant="secondary" disabled={!rangeIsValid} busy={busy === "period"} onClick={() => void createPeriod()}>Создать период</Button>
            </div>
          ) : selectedPeriod && (
            <div className="period-workflow">
              {periods.length > 1 && <Field label="Период"><Select value={selectedPeriod.id} onChange={(event) => setPeriodId(event.target.value)}>{periods.map((period) => <option value={period.id} key={period.id}>{formatDate(period.dateFrom)} — {formatDate(period.dateTo)} · {periodStatusLabels[period.status]}</option>)}</Select></Field>}
              <div className="period-overview">
                <div><small>Выбранный период</small><strong>{formatDate(selectedPeriod.dateFrom)} — {formatDate(selectedPeriod.dateTo)}</strong></div>
                <Badge value={selectedPeriod.status} label={periodStatusLabels[selectedPeriod.status]} />
              </div>
              <ol className="approval-progress">
                {approvalSteps.map((step, index) => <li key={step.status} className={index < currentStepIndex ? "complete" : index === currentStepIndex ? "current" : ""}><span>{index < currentStepIndex ? "✓" : index + 1}</span><small>{step.label}</small></li>)}
              </ol>
              <div className="period-next-action">
                {selectedPeriod.status === "Open" && <><strong>Всё проверено?</strong><p>После отправки табель нельзя редактировать до повторного открытия.</p><Button busy={busy === "submit"} onClick={() => void periodAction("submit")}>Отправить на согласование</Button></>}
                {selectedPeriod.status === "Submitted" && <><strong>Табель ожидает согласования</strong><p>Проверьте часы и отсутствия, затем подтвердите период.</p><Button busy={busy === "approve"} onClick={() => void periodAction("approve")}>Согласовать период</Button></>}
                {selectedPeriod.status === "Approved" && <><strong>Период согласован</strong><p>Закройте его, чтобы окончательно защитить записи от изменений.</p><Button busy={busy === "lock"} onClick={() => void periodAction("lock")}>Закрыть период</Button></>}
                {selectedPeriod.status === "Locked" && <><strong>Период закрыт</strong><p>Все записи защищены. Для исправлений период потребуется открыть заново.</p><Button variant="ghost" onClick={() => setShowReopen(true)}>Открыть для исправлений</Button></>}
              </div>
              <p className="period-scope-note">Согласование применяется ко всем сформированным табелям сотрудников внутри этого периода.</p>
            </div>
          )}
        </Panel>
      </div>

      <div ref={timesheetSectionRef}>
        <Panel
          className="timesheet-table-panel"
          title="Табель за выбранный период"
          description={timesheet ? `${timesheet.employeeName} · ${formatDate(timesheet.dateFrom)} — ${formatDate(timesheet.dateTo)}` : "После выбора сотрудника здесь появятся все строки табеля, а не только уведомление о формировании."}
          actions={employeeId && rangeIsValid ? <Button type="button" variant="ghost" disabled={timesheetLoading} onClick={() => void loadTimesheet()}>Обновить</Button> : undefined}
        >
        {!employeeId ? (
          <EmptyState title="Сотрудник не выбран" description="Выберите сотрудника в календаре выше, чтобы открыть его табель." />
        ) : timesheetLoading ? (
          <Loading label="Загружаем строки табеля" />
        ) : !timesheet ? (
          <EmptyState title="Табель пока недоступен" description="Проверьте выбранные даты и повторите загрузку." />
        ) : (
          <>
            <div className="result-grid timesheet-summary">
              <div><strong>{timesheet.plannedWorkingDays}</strong><span>рабочих дней</span></div>
              <div><strong>{timesheet.completedWorkingDays}</strong><span>дней с фактом</span></div>
              <div><strong>{minutesToHours(timesheet.plannedMinutes)}</strong><span>план</span></div>
              <div><strong>{minutesToHours(timesheet.actualMinutes)}</strong><span>факт</span></div>
              <div><strong>{minutesToHours(timesheet.overtimeMinutes)}</strong><span>сверхурочно</span></div>
              <div><strong>{minutesToHours(timesheet.absenceMinutes)}</strong><span>отсутствие</span></div>
            </div>
            <div className="table-wrap timesheet-table-wrap">
              <table className="timesheet-table">
                <thead>
                  <tr><th>Дата</th><th>График</th><th>Смена</th><th>План</th><th>Факт</th><th>Сверх.</th><th>Отсутствие</th><th>Статус</th><th>Источник</th><th>Комментарий / причина</th><th>Период</th></tr>
                </thead>
                <tbody>
                  {timesheet.days.map((day) => (
                    <tr key={day.date} className={day.isManualOverride ? "manual-timesheet-row" : day.attendanceStatus === "MissingSchedule" ? "warning-timesheet-row" : ""}>
                      <td><strong>{formatDate(day.date)}</strong></td>
                      <td>{day.scheduleName ?? "—"}</td>
                      <td>{formatShift(day.plannedStartTime, day.plannedEndTime, day.crossesMidnight)}</td>
                      <td>{minutesToHours(day.plannedMinutes)}</td>
                      <td>{day.date > todayDate ? minutesToHours(0) : day.actualMinutes == null ? "—" : minutesToHours(day.actualMinutes)}</td>
                      <td>{day.overtimeMinutes > 0 ? minutesToHours(day.overtimeMinutes) : "—"}</td>
                      <td>{day.absenceMinutes > 0 ? <>{minutesToHours(day.absenceMinutes)}{day.paymentPercent != null && <small> · оплата {day.paymentPercent.toLocaleString("ru-RU")}%</small>}</> : "—"}</td>
                      <td><span className={`timesheet-status status-${day.attendanceStatus.toLowerCase()}`}>{attendanceLabels[day.attendanceStatus] ?? day.attendanceStatus}</span></td>
                      <td>{day.isManualOverride ? <strong className="manual-source">Вручную</strong> : sourceLabels[day.source] ?? day.source}</td>
                      <td>{[day.comment, day.reason].filter(Boolean).join(" · ") || "—"}</td>
                      <td>{day.periodStatus ? periodStatusLabels[day.periodStatus as TimesheetPeriodListItem["status"]] ?? day.periodStatus : "Не сформирован"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </>
        )}
        </Panel>
      </div>

      {employeeId && <ManualChanges key={employeeId} employeeId={employeeId} revision={changesRevision} />}
      {showCalculation && employeeId && <PayCalculationModal key={employeeId} employeeId={employeeId} employeeName={selectedEmployee?.displayName || ""} from={dateFrom} to={dateTo} onClose={()=>setShowCalculation(false)} />}

      {selectedDay && <Modal title={`Факт за ${new Intl.DateTimeFormat("ru-RU").format(new Date(`${selectedDay.date}T00:00:00`))}`} onClose={() => setSelectedDay(null)}>
        <div className="day-summary"><span>План: {minutesToHours(selectedDay.plannedMinutes)}</span><span>Статус: {attendanceLabels[selectedDay.attendanceStatus] ?? selectedDay.attendanceStatus}</span></div>
        {selectedDay.isManualOverride && <Alert tone="success">Эта запись внесена вручную и не будет заменена автоматическим пересчётом.</Alert>}
        {selectedDay.changeReason && <Alert tone="info">{selectedDay.source === "ScheduleOverride" ? "Причина исключения из графика" : "Последняя причина изменения"}: {selectedDay.changeReason}{selectedDay.updatedBy ? ` · ${selectedDay.updatedBy}` : ""}</Alert>}
        {selectedDay.absenceReason && selectedDay.absenceReason !== selectedDay.changeReason && <Alert tone="info">Основание отсутствия: {selectedDay.absenceReason}</Alert>}
        {selectedDay.paymentPercent != null && <Alert tone="info">Оплата отсутствия: {selectedDay.paymentPercent.toLocaleString("ru-RU")}%</Alert>}
        {selectedDay.canEdit ? <form className="form-grid" onSubmit={adjustDay}>
          <Field label="Факт, часов"><Input name="actualHours" type="number" min={0} max={48} step="any" defaultValue={(selectedDay.actualMinutes ?? 0) / 60} required autoFocus /></Field>
          <Field label="Сверхурочно, часов"><Input name="overtimeHours" type="number" min={0} max={48} step="any" defaultValue={selectedDay.overtimeMinutes / 60} /></Field>
          <Field label="Комментарий" wide><Input name="comment" defaultValue={selectedDay.comment ?? ""} maxLength={500} /></Field>
          <Field label="Причина нового изменения" wide><Input name="reason" required minLength={3} maxLength={500} /></Field>
          <div className="form-actions field-wide"><Button type="button" variant="ghost" onClick={() => setSelectedDay(null)}>Отмена</Button><Button type="submit" busy={busy === "adjust"}>Сохранить факт</Button></div>
        </form> : <><Alert tone="warning">Эту строку нельзя изменить: запись ещё не сформирована либо период уже не открыт.</Alert><div className="form-actions"><Button type="button" variant="ghost" onClick={() => setSelectedDay(null)}>Закрыть</Button></div></>}
      </Modal>}

      {showAbsence && <Modal title="Зарегистрировать отсутствие" onClose={() => setShowAbsence(false)}>
        <form className="form-grid" onSubmit={createAbsence}>
          <Field label="Сотрудник" wide><EmployeeSelect employees={employees} value={employeeId} onChange={setEmployeeId} required /></Field>
          <Field label="С"><Input name="dateFrom" type="date" defaultValue={dateFrom} required /></Field><Field label="По"><Input name="dateTo" type="date" defaultValue={dateTo} required /></Field>
          <Field label="Вид"><Select name="type" value={absenceType} onChange={(event) => { const type = event.target.value; setAbsenceType(type); setAbsencePayTreatment(type === "4" || type === "7" ? "2" : type === "3" ? "4" : "1"); }}><option value="1">Уважительное отсутствие</option><option value="2">Отпуск</option><option value="3">Больничный</option><option value="4">Неоплачиваемый отпуск</option><option value="5">Оплачиваемый отпуск</option><option value="6">Командировка</option><option value="7">Прогул</option><option value="8">Другое</option></Select></Field>
          <Field label="Оплата"><Select name="payTreatment" value={absencePayTreatment} onChange={(event) => setAbsencePayTreatment(event.target.value)} disabled={absenceMustBeUnpaid}><option value="1">Оплачивается полностью (100%)</option><option value="4">По указанному проценту</option><option value="2">Не оплачивается (0%)</option><option value="3">Только информация</option></Select></Field>
          {absencePayTreatment === "4" && <Field label="Процент оплаты" hint="От 0 до 100% от ставки за часы отсутствия"><Input name="paymentPercent" type="number" min={0} max={100} step={0.01} defaultValue={100} required /></Field>}
          {absenceMustBeUnpaid && <p className="period-scope-note field-wide">Эти часы не оплачиваются и уменьшают начисление зарплаты.</p>}
          <Field label="Минут в день" hint="Оставьте пустым для полного дня"><Input name="durationMinutes" type="number" min={1} max={1440} /></Field>
          <Field label="Основание"><Input name="reason" required maxLength={500} /></Field>
          <div className="form-actions field-wide"><Button type="button" variant="ghost" onClick={() => setShowAbsence(false)}>Отмена</Button><Button type="submit" busy={busy === "absence"}>Зарегистрировать</Button></div>
        </form>
      </Modal>}

      {showReopen && selectedPeriod && <Modal title="Открыть период для исправлений" onClose={() => setShowReopen(false)}>
        <Alert tone="warning">После открытия записи снова можно будет изменять. Укажите понятную причину для журнала аудита.</Alert>
        <form className="stack-form" onSubmit={reopenPeriod}>
          <Field label="Причина"><Input name="reason" required minLength={3} maxLength={1000} autoFocus placeholder="Например: исправление часов за 12 сентября" /></Field>
          <div className="form-actions"><Button type="button" variant="ghost" onClick={() => setShowReopen(false)}>Отмена</Button><Button type="submit" busy={busy === "reopen"}>Открыть период</Button></div>
        </form>
      </Modal>}
    </>
  );
}
