import {useState, type FormEvent} from "react";
import {apiRequest, errorMessage, jsonBody} from "../api/client";
import {Alert, Button, Field, Input, Modal, formatDate, minutesToHours} from "./ui";
interface Calculation {
  currency:string; plannedMinutes:number; actualMinutes:number; overtimeMinutes:number; underworkedMinutes:number;
  baseAmount:number; overtimeAmount:number; bonusAmount:number; totalAmount:number;
  rates:{validFrom:string; validTo?:string; compensationType:string; amount:number; actualMinutes:number; monthlyNormMinutes?:number}[];
}
export function PayCalculationModal({employeeId, employeeName, from, to, onClose}:{employeeId:string; employeeName:string; from:string; to:string; onClose:()=>void}) {
  const [dateFrom,setFrom]=useState(from), [dateTo,setTo]=useState(to);
  const [bonus,setBonus]=useState("0"), [hourBonus,setHourBonus]=useState("0");
  const [result,setResult]=useState<Calculation|null>(null), [busy,setBusy]=useState(false), [error,setError]=useState("");
  const money=(value:number)=>value.toLocaleString("ru-RU",{minimumFractionDigits:2,maximumFractionDigits:2})+" "+result?.currency;
  const calculate=async (e:FormEvent)=>{
    e.preventDefault();setBusy(true);setResult(null);setError("");
    try {setResult(await apiRequest<Calculation>(`/api/employees/${employeeId}/pay-calculation`,{method:"POST",...jsonBody({dateFrom,dateTo,bonus:Number(bonus),overtimeBonusPerHour:Number(hourBonus)})}));}
    catch(err){setError(errorMessage(err));}finally{setBusy(false);}
  };
  return <Modal title="Рассчитать период" onClose={onClose}>
    <p><strong>{employeeName}</strong></p>
    <form className="stack-form" onSubmit={calculate} onChange={()=>setResult(null)}>
      <div className="form-grid"><Field label="Рассчитать с"><Input disabled={busy} type="date" value={dateFrom} onChange={e=>setFrom(e.target.value)} required /></Field><Field label="Рассчитать по включительно"><Input disabled={busy} type="date" value={dateTo} min={dateFrom} onChange={e=>setTo(e.target.value)} required /></Field></div>
      <div className="form-grid"><Field label="Надбавка за период"><Input disabled={busy} type="number" min={0} max={1000000000} step="0.01" value={bonus} onChange={e=>setBonus(e.target.value)} required /></Field><Field label="Дополнительно за час переработки"><Input disabled={busy} type="number" min={0} max={1000000000} step="0.01" value={hourBonus} onChange={e=>setHourBonus(e.target.value)} required /></Field></div>
      <p className="period-scope-note">Каждый расчёт использует актуальные часы и ставки, включая изменения задним числом. Оклад делится на полную месячную норму графика. Будущие дни не оплачиваются; текущий день учитывается по внесённому факту.</p>
      {error && <Alert tone="error">{error}</Alert>}
      <Button type="submit" busy={busy} disabled={dateFrom>dateTo}>Рассчитать сумму</Button>
    </form>
    {result && <div className="pay-calculation-result" aria-live="polite">
      <div className="result-grid"><div><strong>{minutesToHours(result.plannedMinutes)}</strong><span>План учтённых дней</span></div><div><strong>{minutesToHours(result.actualMinutes)}</strong><span>Фактически отработано</span></div><div><strong>{minutesToHours(result.overtimeMinutes)}</strong><span>Переработка</span></div><div><strong>{minutesToHours(result.underworkedMinutes)}</strong><span>Недоработка</span></div></div>
      <div className="table-wrap"><table><thead><tr><th>Действие ставки</th><th>Ставка</th><th>Факт</th><th>Норма месяца</th></tr></thead><tbody>{result.rates.map((rate,index)=><tr key={index}><td>{formatDate(rate.validFrom)} — {rate.validTo ? formatDate(rate.validTo) : "бессрочно"}</td><td>{money(rate.amount)} / {rate.compensationType === "Hourly" ? "час" : "мес."}</td><td>{minutesToHours(rate.actualMinutes)}</td><td>{rate.monthlyNormMinutes ? minutesToHours(rate.monthlyNormMinutes) : "—"}</td></tr>)}</tbody></table></div>
      <dl className="pay-breakdown"><div><dt>Основная оплата</dt><dd>{money(result.baseAmount)}</dd></div><div><dt>Оплата переработки</dt><dd>{money(result.overtimeAmount)}</dd></div><div><dt>Дополнительные надбавки</dt><dd>{money(result.bonusAmount)}</dd></div></dl>
      <div className="salary-total"><span>Итого за период</span><strong>{money(result.totalAmount)}</strong></div>
    </div>}
  </Modal>;
}
