import {useCallback, useEffect, useRef, useState, type FormEvent} from "react";
import {apiRequest, jsonBody, queryString} from "../api/client";
import {Alert, Badge, Button, EmployeeSelect, EmptyState, Field, Input, Loading, PageHeader, Panel, Select, Textarea, formatDateTime} from "../components/ui";
import {useEmployees} from "../hooks/useEmployees";
import type {EmployeeTelegramChannel, NotificationHistoryItem, TelegramAccountLink, TelegramBotSettings, TelegramBotStatus} from "../types";
import {notificationKinds, notificationStatusLabel, telegramError, telegramProblem} from "./telegramSetup";

export function NotificationsPage() {
  const pageRef = useRef<HTMLDivElement>(null);
  const {employees, error: employeeError} = useEmployees();
  const [employeeId, setEmployeeId] = useState("");
  const employeeRef = useRef(employeeId); employeeRef.current = employeeId;
  const historyRequest = useRef(0);
  const [history, setHistory] = useState<NotificationHistoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState("");
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [botSettings, setBotSettings] = useState<TelegramBotSettings | null>(null);
  const [botEnabled, setBotEnabled] = useState(false);
  const [botToken, setBotToken] = useState("");
  const [chatId, setChatId] = useState("");
  const [channelEnabled, setChannelEnabled] = useState(false);
  const [channelLoading, setChannelLoading] = useState(false);
  const [channelVerified, setChannelVerified] = useState(false);
  const [botStatus, setBotStatus] = useState<TelegramBotStatus | null>(null);
  const [accountLink, setAccountLink] = useState<TelegramAccountLink | null>(null);
  const [testNotification, setTestNotification] = useState<{id: string; employeeId: string; until: number} | null>(null);
  const botDirty = Boolean(botToken.trim()) || botEnabled !== botSettings?.enabled;
  const botReady = Boolean(botSettings?.enabled && botStatus?.isConnected && !botDirty);
  const channelReady = Boolean(employeeId && channelEnabled && channelVerified && !channelLoading);
  const canSend = Boolean(botReady && employeeId && channelEnabled && !channelLoading && !busy);
  const testResult = testNotification?.employeeId === employeeId ? history.find(item => item.id === testNotification.id) : undefined;
  const employeeName = employees.find(employee => employee.id === employeeId)?.displayName;

  const loadBotSettings = useCallback(async () => {
    try {
      const settings = await apiRequest<TelegramBotSettings>("/api/notifications/telegram/settings");
      setBotSettings(settings); setBotEnabled(settings.enabled);
      setBotStatus(await apiRequest<TelegramBotStatus>("/api/notifications/telegram/bot/status"));
    } catch (requestError) {setError(telegramError(requestError));}
  }, []);
  useEffect(() => {void loadBotSettings();}, [loadBotSettings]);

  const applyChannel = (channel: EmployeeTelegramChannel) => {
    setChatId(channel.chatId ?? ""); setChannelEnabled(channel.isEnabled); setChannelVerified(Boolean(channel.isVerified));
  };
  useEffect(() => {
    let active = true;
    setChatId(""); setChannelEnabled(false); setChannelVerified(false); setAccountLink(null); setChannelLoading(Boolean(employeeId));
    if (employeeId) {
      void apiRequest<EmployeeTelegramChannel>(`/api/employees/${employeeId}/notification-channels/telegram`)
        .then(channel => {if (active) applyChannel(channel);})
        .catch(requestError => {if (active) setError(telegramError(requestError));})
        .finally(() => {if (active) setChannelLoading(false);});
    }
    return () => {active = false;};
  }, [employeeId]);

  useEffect(() => {
    if (!employeeId || !accountLink || !botReady) return;
    let active = true;
    let timer: ReturnType<typeof setTimeout>;
    const refresh = async () => {
      if (Date.parse(accountLink.expiresAt) <= Date.now()) {
        if (active) {setAccountLink(null); setNotice("Ссылка подключения истекла. Создайте новую.");}
        return;
      }
      try {
        const channel = await apiRequest<EmployeeTelegramChannel>(`/api/employees/${employeeId}/notification-channels/telegram`);
        if (!active) return;
        if (channel.isVerified && channel.isEnabled) {
          applyChannel(channel); setAccountLink(null); setNotice("Telegram сотрудника подключён. Chat ID сохранён автоматически."); return;
        }
      } catch (requestError) {if (active) setError(telegramError(requestError));}
      if (active) timer = setTimeout(() => void refresh(), 3000);
    };
    timer = setTimeout(() => void refresh(), 3000);
    return () => {active = false; clearTimeout(timer);};
  }, [employeeId, accountLink, botReady]);

  const applyBotStatus = (status: TelegramBotStatus) => {
    setBotStatus(status);
    setBotSettings(current => current && {...current, isConnected: status.isConnected, botUsername: status.botUsername});
    if (!status.isConnected) setAccountLink(null);
  };
  const connectSavedBot = async () => {
    const status = await apiRequest<TelegramBotStatus>("/api/notifications/telegram/bot/connect", {method: "POST"});
    applyBotStatus(status);
    if (!status.isConnected) throw new Error("Бот пока не подключён. Проверьте токен и повторите подключение.");
    setNotice("Бот подключён к CRM. Теперь выберите сотрудника во втором шаге.");
    const selected = employeeRef.current;
    if (selected) {
      const channel = await apiRequest<EmployeeTelegramChannel>(`/api/employees/${selected}/notification-channels/telegram`);
      if (employeeRef.current === selected) applyChannel(channel);
    }
  };
  const persistBot = async (enabled: boolean, connect: boolean) => {
    setError(""); setNotice("");
    if (enabled && !botSettings?.hasBotToken && !botToken.trim()) {setError("Введите токен бота, чтобы включить Telegram."); return;}
    setBusy(connect ? "setup" : "bot");
    try {
      const settings = await apiRequest<TelegramBotSettings>("/api/notifications/telegram/settings", {
        method: "PUT", ...jsonBody({enabled, botToken: botToken.trim() || null}),
      });
      setBotSettings(settings); setBotEnabled(settings.enabled); setBotToken("");
      if (!settings.isConnected) {setBotStatus(null); setAccountLink(null); setChannelVerified(false);}
      if (connect) await connectSavedBot();
      else setNotice("Настройки бота сохранены. Они применяются без перезапуска сервера.");
    } catch (requestError) {setError(telegramError(requestError));}
    finally {setBusy("");}
  };
  const saveBotSettings = (event: FormEvent<HTMLFormElement>) => {event.preventDefault(); void persistBot(botEnabled, false);};
  const connectBot = async () => {
    setBusy("connect"); setError(""); setNotice("");
    try {await connectSavedBot();} catch (requestError) {setError(telegramError(requestError));}
    finally {setBusy("");}
  };
  const refreshBotStatus = async () => {
    setBusy("status"); setError(""); setNotice("");
    try {applyBotStatus(await apiRequest<TelegramBotStatus>("/api/notifications/telegram/bot/status"));}
    catch (requestError) {setError(telegramError(requestError));} finally {setBusy("");}
  };
  const createAccountLink = async () => {
    if (!employeeId || !botReady) return;
    const selected = employeeId;
    setBusy("link"); setError(""); setNotice("");
    try {
      const link = await apiRequest<TelegramAccountLink>(`/api/employees/${selected}/notification-channels/telegram/link`, {method: "POST"});
      if (employeeRef.current !== selected) return;
      setAccountLink(link); setNotice("Передайте ссылку выбранному сотруднику. После нажатия «Старт» канал обновится автоматически.");
    } catch (requestError) {if (employeeRef.current === selected) setError(telegramError(requestError));}
    finally {setBusy("");}
  };
  const copyLink = async () => {
    if (!accountLink) return;
    try {await navigator.clipboard.writeText(accountLink.url); setNotice("Ссылка скопирована. Отправьте её выбранному сотруднику.");}
    catch {setError("Не удалось скопировать ссылку. Выделите её в поле и скопируйте вручную.");}
  };

  const loadHistory = useCallback(async (background = false) => {
    const requestId = ++historyRequest.current;
    if (!background) {setLoading(true); setHistory([]);}
    try {
      const items = await apiRequest<NotificationHistoryItem[]>(`/api/notifications/history?${queryString({employeeId, page: 1, pageSize: 50})}`);
      if (employeeRef.current === employeeId && historyRequest.current === requestId) setHistory(items);
    } catch (requestError) {if (employeeRef.current === employeeId) setError(telegramError(requestError));}
    finally {if (historyRequest.current === requestId) setLoading(false);}
  }, [employeeId]);
  useEffect(() => {void loadHistory();}, [loadHistory]);
  useEffect(() => {
    if (!testNotification || testNotification.employeeId !== employeeId || testResult?.status === "Delivered" || testResult?.status === "DeadLetter") return;
    const timer = setTimeout(() => {if (Date.now() < testNotification.until) void loadHistory(true);}, 3000);
    return () => clearTimeout(timer);
  }, [testNotification, employeeId, testResult, history, loadHistory]);

  const saveTelegram = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!employeeId || !chatId.trim()) return;
    const selected = employeeId;
    setBusy("telegram"); setError(""); setNotice("");
    try {
      await apiRequest(`/api/employees/${selected}/notification-channels/telegram`, {method: "PUT", ...jsonBody({chatId: chatId.trim()})});
      if (employeeRef.current === selected) {setChannelEnabled(true); setChannelVerified(false); setAccountLink(null); setNotice("Telegram-канал сохранён.");}
    } catch (requestError) {setError(telegramError(requestError));} finally {setBusy("");}
  };
  const disableTelegram = async () => {
    if (!employeeId) return;
    const selected = employeeId;
    setBusy("disable"); setError(""); setNotice("");
    try {
      await apiRequest(`/api/employees/${selected}/notification-channels/telegram`, {method: "DELETE"});
      if (employeeRef.current === selected) {setChannelEnabled(false); setChannelVerified(false); setAccountLink(null); setNotice("Telegram-канал отключён. Неиспользованные ссылки отозваны.");}
    } catch (requestError) {setError(telegramError(requestError));} finally {setBusy("");}
  };
  const sendTest = async () => {
    if (!canSend) return;
    const selected = employeeId;
    setBusy("test"); setError(""); setNotice("");
    try {
      const {id} = await apiRequest<{id: string}>("/api/notifications/messages", {method: "POST", ...jsonBody({employeeId: selected, message: "Проверка связи с CRM. Telegram-уведомления для вас работают.", kind: 6})});
      if (employeeRef.current !== selected) return;
      setTestNotification({id, employeeId: selected, until: Date.now() + 60000});
      setNotice("Проверочное сообщение поставлено в очередь. Статус доставки обновится автоматически.");
      await loadHistory(true);
    } catch (requestError) {setError(telegramError(requestError));} finally {setBusy("");}
  };
  const sendMessage = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!canSend) return;
    const form = event.currentTarget; const data = new FormData(form);
    setBusy("message"); setError(""); setNotice("");
    try {
      await apiRequest("/api/notifications/messages", {method: "POST", ...jsonBody({employeeId, message: data.get("message"), kind: Number(data.get("kind"))})});
      form.reset(); setNotice("Сообщение принято в надёжную очередь отправки."); await loadHistory();
    } catch (requestError) {setError(telegramError(requestError));} finally {setBusy("");}
  };

  const currentStep = !botReady ? 1 : !channelReady ? 2 : 3;
  return <div className="telegram-page" ref={pageRef}>
    <PageHeader eyebrow="Коммуникации" title="Telegram и уведомления" description="Три шага: подключите бота, привяжите сотрудника и проверьте доставку." />
    <nav className="telegram-steps" aria-label="Шаги настройки Telegram">
      {[{id: 1, title: "Подключить бота", done: botReady}, {id: 2, title: "Подключить сотрудника", done: botReady && channelReady}, {id: 3, title: "Проверить доставку", done: testResult?.status === "Delivered"}].map(step =>
        <button type="button" key={step.id} aria-current={currentStep === step.id ? "step" : undefined} className={step.done ? "is-done" : ""} onClick={() => {
          const panel = pageRef.current?.querySelector<HTMLElement>(`#telegram-step-${step.id}`);
          panel?.scrollIntoView({behavior: "smooth", block: "start"}); panel?.focus({preventScroll: true});
        }}>
          <span className="telegram-step-number" aria-hidden="true">{step.done ? "✓" : step.id}</span><span><strong>{step.title}</strong><small>{step.done ? "Готово" : currentStep === step.id ? "Текущий шаг" : "Следующий шаг"}</small></span>
        </button>)}
    </nav>
    {(error || employeeError) && <Alert tone="error">{error || employeeError}</Alert>}
    {notice && <Alert tone="success" onClose={() => setNotice("")}>{notice}</Alert>}
    <div id="telegram-step-1" className="telegram-step-panel" tabIndex={-1}>
      <Panel title="1. Telegram-бот компании" description="Один бот для выбранной компании. Токен хранится зашифрованным и не отображается после сохранения." actions={<Badge value={botReady ? "active" : "pending"} label={botReady ? "Подключён" : botDirty && botSettings?.hasBotToken ? "Есть несохранённые изменения" : "Требуется настройка"} />}>
        <details className="telegram-help" open={!botSettings?.hasBotToken}>
          <summary>Как получить токен бота</summary>
          <ol><li>Откройте <a href="https://t.me/BotFather" target="_blank" rel="noreferrer">@BotFather в Telegram ↗</a> и отправьте команду <code>/newbot</code>.</li><li>Задайте имя и адрес бота, следуя подсказкам BotFather.</li><li>Скопируйте выданный токен, вставьте его ниже и нажмите «Сохранить и подключить».</li></ol>
          <a href="https://core.telegram.org/bots/tutorial#obtain-your-bot-token" target="_blank" rel="noreferrer">Инструкция Telegram ↗</a>
        </details>
        {botSettings === null ? <Button type="button" variant="ghost" onClick={() => void loadBotSettings()}>Загрузить настройки бота</Button> : <form className="stack-form" aria-label="Настройки Telegram-бота" onSubmit={saveBotSettings}>
          <Field label="Токен бота" hint={botSettings.hasBotToken ? "Токен уже сохранён. Оставьте поле пустым, чтобы сохранить его, или введите новый для замены." : "Вставьте токен, полученный у BotFather."}>
            <Input name="botToken" type="password" autoComplete="new-password" value={botToken} onChange={event => setBotToken(event.target.value)} maxLength={256} disabled={Boolean(busy)} placeholder={botSettings.hasBotToken ? "Токен настроен" : "Токен от BotFather"} />
          </Field>
          <div className="button-row"><Button type="button" busy={busy === "setup"} disabled={Boolean(busy)} onClick={() => void persistBot(true, true)}>Сохранить и подключить</Button>
            <Button type="button" variant="ghost" busy={busy === "connect"} disabled={!botSettings.enabled || !botSettings.hasBotToken || Boolean(busy) || botDirty} onClick={() => void connectBot()}>Подключить бота к CRM</Button>
            <Button type="button" variant="ghost" busy={busy === "status"} disabled={Boolean(busy) || !botSettings.hasBotToken || botDirty} onClick={() => void refreshBotStatus()}>Проверить состояние</Button></div>
          {botStatus?.isConnected && <div className="telegram-connection"><strong>Подключён бот @{botStatus.botUsername}</strong><span>Последняя проверка сообщений: {formatDateTime(botStatus.lastPollAt)}.</span></div>}
          {botStatus?.lastErrorCode && <Alert tone="warning">{telegramProblem(botStatus.lastErrorCode)}</Alert>}
          {botDirty && botSettings.hasBotToken && <Alert>Сохраните изменения, чтобы продолжить настройку сотрудников.</Alert>}
          <details className="telegram-help"><summary>Включить или приостановить уведомления</summary><div className="stack-form">
            <Field label="Отправка уведомлений"><Select name="enabled" value={String(botEnabled)} onChange={event => setBotEnabled(event.target.value === "true")} disabled={Boolean(busy)}><option value="false">Отключена</option><option value="true">Включена</option></Select></Field>
            <Button type="submit" variant="secondary" busy={busy === "bot"} disabled={Boolean(busy)}>Сохранить настройки бота</Button></div>
          </details>
        </form>}
      </Panel>
    </div>
    <div className="two-column align-start">
      <div id="telegram-step-2" className="telegram-step-panel" tabIndex={-1}>
        <Panel title="2. Подключить сотрудника" description="CRM сама сохранит его Telegram после перехода по персональной ссылке." actions={<Badge value={channelReady ? "active" : "pending"} label={channelReady ? "Подтверждён" : "Не подтверждён"} />}>
          <form className="stack-form" aria-label="Telegram-канал сотрудника" onSubmit={saveTelegram}>
            <Field label="Сотрудник"><EmployeeSelect employees={employees} value={employeeId} onChange={setEmployeeId} disabled={Boolean(busy)} required /></Field>
            {!botReady && <Alert>Сначала подключите бота в шаге 1.</Alert>}
            {employeeId && <div className="telegram-connection" role="status">{channelLoading ? "Загружаем канал…" : channelEnabled ? channelVerified ? "Канал включён и подтверждён ботом" : "Канал указан вручную. Подтвердите его по ссылке или проверьте доставку." : "Telegram сотрудника ещё не подключён"}</div>}
            <Button type="button" busy={busy === "link"} disabled={!employeeId || !botReady || channelReady || channelLoading || Boolean(busy)} onClick={() => void createAccountLink()}>Создать ссылку подключения</Button>
            {accountLink && botReady && <div className="telegram-link-card">
              <Field label="Одноразовая ссылка" hint={`Для ${employeeName || "выбранного сотрудника"}. Действует до ${formatDateTime(accountLink.expiresAt)}.`}><Input readOnly value={accountLink.url} onFocus={event => event.currentTarget.select()} /></Field>
              <div className="button-row"><Button type="button" variant="secondary" onClick={() => void copyLink()}>Скопировать ссылку</Button><a className="button button-ghost" href={accountLink.url} target="_blank" rel="noreferrer">Открыть в Telegram ↗</a></div>
              <p>Передайте ссылку только выбранному сотруднику. Он должен открыть её в своём Telegram и нажать «Старт».</p><span role="status">Ожидаем подключения… Страница обновится автоматически.</span>
            </div>}
            <details className="telegram-help"><summary>Указать Chat ID вручную</summary><div className="stack-form">
              <p>Попросите сотрудника открыть @{botStatus?.botUsername || "вашего бота"}, нажать «Старт» и отправить <code>/chatid</code>. Укажите полученное число.</p>
              <Field label="Telegram Chat ID"><Input name="chatId" value={chatId} onChange={event => setChatId(event.target.value)} disabled={!employeeId || channelLoading || Boolean(busy)} maxLength={200} placeholder="Например, 123456789" /></Field>
              <Button type="submit" variant="secondary" disabled={!employeeId || !chatId.trim() || channelLoading || Boolean(busy)} busy={busy === "telegram"}>Сохранить канал</Button></div>
            </details>
            {(channelEnabled || accountLink) && <Button type="button" variant="ghost" disabled={!employeeId || channelLoading || Boolean(busy)} busy={busy === "disable"} onClick={() => void disableTelegram()}>Отключить канал сотрудника</Button>}
          </form>
        </Panel>
      </div>
      <div id="telegram-step-3" className="telegram-step-panel" tabIndex={-1} role="region" aria-label="Проверка доставки Telegram">
        <Panel title="3. Проверить доставку" description="Отправьте короткое проверочное сообщение выбранному сотруднику.">
          <div className="stack-form"><p>{employeeName ? `Получатель: ${employeeName}` : "Выберите сотрудника во втором шаге."}</p>
            <Button type="button" disabled={!canSend} busy={busy === "test"} onClick={() => void sendTest()}>Отправить проверочное сообщение</Button>
            {!canSend && !busy && <span className="telegram-muted">Для проверки подключите бота и канал сотрудника.</span>}
            {testResult && <Alert tone={testResult.status === "Delivered" ? "success" : testResult.status === "DeadLetter" ? "error" : "info"}>Проверочное сообщение: {notificationStatusLabel(testResult.status)}.{testResult.status === "DeadLetter" ? " Попросите сотрудника открыть бота и нажать «Старт», затем повторите проверку." : ""}</Alert>}
          </div>
        </Panel>
      </div>
    </div>
    <Panel title="Отправить сообщение" description="Выберите тип уведомления и напишите текст. Доставка выполняется в фоне.">
      <form className="stack-form" aria-label="Сообщение сотруднику" onSubmit={sendMessage}>
        <Field label="Получатель"><EmployeeSelect employees={employees} value={employeeId} onChange={setEmployeeId} disabled={Boolean(busy)} required /></Field>
        <Field label="Тип уведомления"><Select name="kind" defaultValue="5">{notificationKinds.map(kind => <option key={kind.id} value={kind.id}>{kind.label}</option>)}</Select></Field>
        <Field label="Текст"><Textarea name="message" rows={4} minLength={1} maxLength={4000} required /></Field>
        <Button type="submit" busy={busy === "message"} disabled={!canSend}>Отправить сообщение</Button>
      </form>
    </Panel>
    <Panel title="История доставки" description="«В очереди» означает, что сообщение принято. «Доставлено» — Telegram подтвердил отправку." actions={<Button type="button" variant="ghost" disabled={loading} onClick={() => void loadHistory()}>Обновить историю</Button>}>
      {loading ? <Loading /> : history.length === 0 ? <EmptyState title="История пуста" description="После первой отправки здесь появится статус сообщения." /> : <div className="table-wrap"><table><thead><tr><th>Создано</th><th>Сотрудник</th><th>Тип</th><th>Статус</th><th>Попытки</th><th>Доставлено</th></tr></thead><tbody>{history.map(item => <tr key={item.id}><td>{formatDateTime(item.createdAt)}</td><td>{employees.find(employee => employee.id === item.employeeId)?.displayName || "Сотрудник недоступен"}</td><td>{notificationKinds.find(kind => kind.key === item.kind || String(kind.id) === item.kind)?.label ?? item.kind}</td><td><Badge value={item.status} label={notificationStatusLabel(item.status)} />{item.lastError && <div className="telegram-muted">{telegramProblem(item.lastError)}</div>}</td><td>{item.attemptCount}</td><td>{formatDateTime(item.deliveredAt)}</td></tr>)}</tbody></table></div>}
    </Panel>
  </div>;
}
