import { useCallback, useEffect, useState, type FormEvent } from "react";
import { ApiError, apiRequest, errorMessage, jsonBody } from "../api/client";
import { Alert, Button, EmployeeSelect, EmptyState, Field, Input, Loading, PageHeader, Panel, Select, today } from "../components/ui";
import { useEmployees } from "../hooks/useEmployees";
import type { GenerateTimesheetResult, PagedResponse, ScheduleTemplateLookupItem } from "../types";

interface ScheduleDayForm {
  dayOfWeek: number;
  label: string;
  isWorkingDay: boolean;
  startTime: string;
  endTime: string;
  breakMinutes: number;
  crossesMidnight: boolean;
}

interface TemplateResponse {
  id: string;
  name: string;
  timeZoneId: string;
  weeklyPlannedMinutes: number;
  message: string;
}

interface ScheduleTemplateListItem {
  id: string;
  name: string;
  timeZoneId: string;
  isActive: boolean;
  workingDays: number;
  weeklyPlannedMinutes: number;
}

interface ScheduleTemplateDay {
  dayOfWeek: number;
  isWorkingDay: boolean;
  startTime: string | null;
  endTime: string | null;
  breakMinutes: number;
  crossesMidnight: boolean;
}

interface ScheduleMutationResponse {
  id: string;
  generation?: GenerateTimesheetResult | null;
}

interface ScheduleFeedback {
  tone: "success" | "warning" | "error";
  message: string;
}

function mutationFeedback(savedMessage: string, generation: GenerateTimesheetResult | null | undefined, pendingMessage: string): ScheduleFeedback {
  if (!generation) return { tone: "success", message: `${savedMessage} ${pendingMessage}` };
  const details = [`Табель: создано строк ${generation.created}, пересчитано ${generation.updated}.`];
  if (generation.errors > 0) details.push(`Не удалось пересчитать строк: ${generation.errors}.`);
  if (generation.skippedManual > 0) details.push(`Ручные строки сохранены без изменений: ${generation.skippedManual}.`);
  const protectedRows = (generation.skippedLocked ?? 0) + (generation.skippedNonEditable ?? 0);
  if (protectedRows > 0) details.push(`Строки закрытых или согласованных периодов сохранены без изменений: ${protectedRows}.`);
  if (generation.missingSchedule > 0) details.push(`Дней без графика: ${generation.missingSchedule}.`);
  return {
    tone: generation.errors > 0 || generation.skippedManual > 0 || protectedRows > 0 || generation.missingSchedule > 0 ? "warning" : "success",
    message: [savedMessage, ...details].join(" "),
  };
}

interface ScheduleTemplateDetails extends Omit<TemplateResponse, "message"> {
  isActive: boolean;
  days: ScheduleTemplateDay[];
}

interface UpdateTemplateResponse {
  template: ScheduleTemplateDetails;
  message: string;
}

const defaultDays = (): ScheduleDayForm[] => [
  [1, "Понедельник"], [2, "Вторник"], [3, "Среда"], [4, "Четверг"], [5, "Пятница"], [6, "Суббота"], [0, "Воскресенье"],
].map(([day, label]) => ({ dayOfWeek: Number(day), label: String(label), isWorkingDay: Number(day) >= 1 && Number(day) <= 5, startTime: "09:00", endTime: "18:00", breakMinutes: 60, crossesMidnight: false }));

export function SchedulesPage() {
  const { employees, error: employeeError } = useEmployees();
  const [templateName, setTemplateName] = useState("Стандартная неделя");
  const [timeZoneId, setTimeZoneId] = useState("Europe/Minsk");
  const [days, setDays] = useState(defaultDays);
  const [createdTemplate, setCreatedTemplate] = useState<TemplateResponse | null>(null);
  const [editingTemplateId, setEditingTemplateId] = useState("");
  const [templateRows, setTemplateRows] = useState<ScheduleTemplateListItem[]>([]);
  const [templateRowsLoading, setTemplateRowsLoading] = useState(true);
  const [employeeId, setEmployeeId] = useState("");
  const [templateId, setTemplateId] = useState("");
  const [templates, setTemplates] = useState<ScheduleTemplateLookupItem[]>([]);
  const [templatesLoading, setTemplatesLoading] = useState(true);
  const [assignmentFrom, setAssignmentFrom] = useState(today());
  const [assignmentTo, setAssignmentTo] = useState("");
  const [overrideEmployeeId, setOverrideEmployeeId] = useState("");
  const [overrideDate, setOverrideDate] = useState(today());
  const [overrideType, setOverrideType] = useState("1");
  const [busy, setBusy] = useState("");
  const [notice, setNotice] = useState("");
  const [error, setError] = useState("");
  const [assignmentFeedback, setAssignmentFeedback] = useState<ScheduleFeedback | null>(null);
  const [overrideFeedback, setOverrideFeedback] = useState<ScheduleFeedback | null>(null);

  const loadTemplates = useCallback(async (preferredId?: string) => {
    setTemplatesLoading(true);
    setTemplateRowsLoading(true);
    try {
      const [items, page] = await Promise.all([
        apiRequest<ScheduleTemplateLookupItem[]>("/api/schedule-templates/lookup"),
        apiRequest<PagedResponse<ScheduleTemplateListItem>>("/api/schedule-templates?page=1&pageSize=100"),
      ]);
      setTemplates(items);
      setTemplateRows(page.items);
      setTemplateId((current) => {
        const next = preferredId ?? current;
        return next && items.some((item) => item.id === next) ? next : "";
      });
    } catch (requestError) {
      setError(errorMessage(requestError));
    } finally {
      setTemplatesLoading(false);
      setTemplateRowsLoading(false);
    }
  }, []);

  useEffect(() => { void loadTemplates(); }, [loadTemplates]);

  const previewDate=new Date();
  const previewDays=Array.from({length:new Date(previewDate.getFullYear(),previewDate.getMonth()+1,0).getDate()},(_,index)=>new Date(previewDate.getFullYear(),previewDate.getMonth(),index+1));
  const previewOffset=(previewDays[0]!.getDay()+6)%7;

  const updateDay = (index: number, patch: Partial<ScheduleDayForm>) => setDays((current) => current.map((day, dayIndex) => dayIndex === index ? { ...day, ...patch } : day));

  const resetTemplateEditor = () => {
    setEditingTemplateId("");
    setTemplateName("Стандартная неделя");
    setTimeZoneId("Europe/Minsk");
    setDays(defaultDays());
  };

  const editTemplate = async (id: string) => {
    setBusy("load-template"); setError("");
    try {
      const template = await apiRequest<ScheduleTemplateDetails>(`/api/schedule-templates/${id}`);
      const templateDays = new Map(template.days.map((day) => [day.dayOfWeek, day]));
      setEditingTemplateId(template.id);
      setTemplateName(template.name);
      setTimeZoneId(template.timeZoneId);
      setDays(defaultDays().map((day) => {
        const saved = templateDays.get(day.dayOfWeek);
        return saved ? {
          ...day,
          isWorkingDay: saved.isWorkingDay,
          startTime: saved.startTime?.slice(0, 5) ?? day.startTime,
          endTime: saved.endTime?.slice(0, 5) ?? day.endTime,
          breakMinutes: saved.breakMinutes,
          crossesMidnight: saved.crossesMidnight,
        } : { ...day, isWorkingDay: false, breakMinutes: 0, crossesMidnight: false };
      }));
      window.scrollTo({ top: 0, behavior: "smooth" });
    } catch (requestError) { setError(errorMessage(requestError)); } finally { setBusy(""); }
  };

  const saveTemplate = async (event: FormEvent) => {
    event.preventDefault(); setBusy("template"); setError(""); setNotice("");
    const payload = { name: templateName, timeZoneId, days: days.map(({ label: _, ...day }) => ({ ...day, startTime: day.isWorkingDay ? day.startTime : null, endTime: day.isWorkingDay ? day.endTime : null, breakMinutes: day.isWorkingDay ? day.breakMinutes : 0, crossesMidnight: day.isWorkingDay && day.crossesMidnight })) };
    try {
      if (editingTemplateId) {
        const response = await apiRequest<UpdateTemplateResponse>(`/api/schedule-templates/${editingTemplateId}`, { method: "PUT", ...jsonBody(payload) });
        setCreatedTemplate({ ...response.template, message: response.message });
        setNotice(response.message);
        resetTemplateEditor();
        await loadTemplates(response.template.id);
      } else {
        const response = await apiRequest<TemplateResponse>("/api/schedule-templates", { method: "POST", ...jsonBody(payload) });
        setCreatedTemplate(response);
        setTemplateId(response.id);
        setNotice(response.message || "Шаблон графика создан и готов к назначению.");
        await loadTemplates(response.id);
      }
    } catch (requestError) { setError(errorMessage(requestError)); } finally { setBusy(""); }
  };

  const assignTemplate = async (event: FormEvent) => {
    event.preventDefault(); setBusy("assignment"); setAssignmentFeedback(null);
    try {
      const payload = {scheduleTemplateId:templateId, validFrom:assignmentFrom, validTo:assignmentTo || null};
      const send = (replaceExisting = false) => apiRequest<ScheduleMutationResponse>(`/api/employees/${employeeId}/schedule-assignments`, {method:"POST", ...jsonBody({...payload, replaceExisting})});
      let response: ScheduleMutationResponse;
      try { response = await send(); }
      catch (e) {
        if (!(e instanceof ApiError) || e.code !== "schedules.confirm_replacement") throw e;
        if (!window.confirm(e.message)) return;
        response = await send(true);
      }
      setAssignmentFeedback(mutationFeedback("График назначен. Изменения сохранены.", response.generation, "Табель будет сформирован с даты начала графика."));
    } catch (requestError) { setAssignmentFeedback({ tone: "error", message: errorMessage(requestError) }); } finally { setBusy(""); }
  };

  const setOverride = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setBusy("override"); setOverrideFeedback(null);
    const data = new FormData(event.currentTarget);
    try {
      if (overrideType === "absence" || overrideType === "sick") {
        await apiRequest("/api/absences", {method:"POST", ...jsonBody({employeeId:overrideEmployeeId, dateFrom:overrideDate, dateTo:overrideDate,
          durationMinutes:null, type:overrideType === "sick" ? 3 : 7, payTreatment:overrideType === "sick" ? 4 : 2,
          paymentPercent:overrideType === "sick" ? Number(data.get("paymentPercent")) : null, reason:data.get("reason")})});
        setOverrideFeedback({tone:"success", message:"Отсутствие сохранено в табеле."}); return;
      }
      const isHours = Number(overrideType) === 2 || Number(overrideType) === 3;
      const response = await apiRequest<ScheduleMutationResponse>(`/api/employees/${overrideEmployeeId}/schedule-overrides/${overrideDate}`, {
        method: "PUT",
        ...jsonBody({ overrideType: Number(overrideType), startTime: isHours ? data.get("startTime") : null, endTime: isHours ? data.get("endTime") : null, breakMinutes: isHours ? Number(data.get("breakMinutes")) : 0, crossesMidnight: data.get("crossesMidnight") === "on", reason: data.get("reason") }),
      });
      setOverrideFeedback(mutationFeedback("Исключение из графика сохранено.", response.generation, "Табель можно обновить в разделе «Табель»."));
    } catch (requestError) { setOverrideFeedback({ tone: "error", message: errorMessage(requestError) }); } finally { setBusy(""); }
  };

  return (
    <>
      <PageHeader eyebrow="Планирование" title="Графики работы" description="Соберите недельный шаблон, назначьте его сотрудникам и учитывайте точечные исключения." />
      {(error || employeeError) && <Alert tone="error">{error || employeeError}</Alert>}
      {notice && <Alert tone="success" onClose={() => setNotice("")}>{notice}</Alert>}

      <Panel title={editingTemplateId ? "Редактирование графика" : "Недельный шаблон"} description="Время хранится в часовом поясе шаблона; ночные смены отмечаются отдельно." actions={editingTemplateId ? <Button variant="ghost" onClick={resetTemplateEditor}>Отменить редактирование</Button> : undefined}>
        <form onSubmit={saveTemplate}>
          <div className="form-grid compact-grid">
            <Field label="Название"><Input value={templateName} onChange={(e) => setTemplateName(e.target.value)} required maxLength={150} /></Field>
            <Field label="Часовой пояс"><Input value={timeZoneId} onChange={(e) => setTimeZoneId(e.target.value)} required /></Field>
          </div>
          <div className="schedule-editor">
            <div className="schedule-editor-head"><span>День</span><span>Рабочий</span><span>Начало</span><span>Окончание</span><span>Перерыв</span><span>Ночная</span></div>
            {days.map((day, index) => (
              <div className={`schedule-row ${day.isWorkingDay ? "" : "day-off"}`} key={day.dayOfWeek}>
                <strong>{day.label}</strong>
                <label className="switch"><input type="checkbox" checked={day.isWorkingDay} onChange={(e) => updateDay(index, { isWorkingDay: e.target.checked })} /><span /></label>
                <Input aria-label={`Начало, ${day.label}`} type="time" value={day.startTime} disabled={!day.isWorkingDay} onChange={(e) => updateDay(index, { startTime: e.target.value })} />
                <Input aria-label={`Окончание, ${day.label}`} type="time" value={day.endTime} disabled={!day.isWorkingDay} onChange={(e) => updateDay(index, { endTime: e.target.value })} />
                <Input aria-label={`Перерыв, ${day.label}`} type="number" min={0} max={720} value={day.breakMinutes} disabled={!day.isWorkingDay} onChange={(e) => updateDay(index, { breakMinutes: Number(e.target.value) })} />
                <label className="switch"><input type="checkbox" checked={day.crossesMidnight} disabled={!day.isWorkingDay} onChange={(e) => updateDay(index, { crossesMidnight: e.target.checked })} /><span /></label>
              </div>
            ))}
          </div>
          <div className="form-actions"><Button type="submit" busy={busy === "template"}>{editingTemplateId ? "Сохранить изменения" : "Создать график"}</Button></div>
        </form>
        <div className="schedule-month-preview"><h3>{new Intl.DateTimeFormat("ru-RU",{month:"long",year:"numeric"}).format(previewDate)} · предпросмотр графика</h3><div className="calendar-grid">{["Пн","Вт","Ср","Чт","Пт","Сб","Вс"].map(day=><div className="weekday" key={day}>{day}</div>)}{Array.from({length:previewOffset},(_,index)=><div key={`empty-${index}`} />)}{previewDays.map(date=>{
          const day=days.find(item=>item.dayOfWeek===date.getDay())!;
          const dateValue=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;
          return <div key={date.getDate()} className={`calendar-day ${day.isWorkingDay ? "working" : "off"} ${dateValue<today() ? "past" : ""} ${dateValue===today() ? "today" : ""}`}><span className="day-number">{date.getDate()}</span><small>{day.isWorkingDay ? day.startTime+"–"+day.endTime : "Выходной"}</small></div>;
        })}</div></div>
      </Panel>

      <Panel title="Созданные графики" description="Откройте любой график, чтобы изменить его название, часовой пояс или рабочие дни." actions={<Button variant="ghost" onClick={() => void loadTemplates()} disabled={templatesLoading}>Обновить</Button>}>
        {templateRowsLoading ? <Loading label="Загружаем графики" /> : templateRows.length === 0 ? <EmptyState title="Графиков пока нет" description="Создайте первый недельный график выше." /> : (
          <div className="table-wrap">
            <table>
              <thead><tr><th>Название</th><th>Часовой пояс</th><th>Рабочих дней</th><th>Часов в неделю</th><th><span className="sr-only">Действия</span></th></tr></thead>
              <tbody>{templateRows.map((template) => (
                <tr key={template.id}>
                  <td><strong>{template.name}</strong></td>
                  <td>{template.timeZoneId}</td>
                  <td>{template.workingDays}</td>
                  <td>{(template.weeklyPlannedMinutes / 60).toLocaleString("ru-RU", { maximumFractionDigits: 1 })}</td>
                  <td><div className="row-actions"><button onClick={() => void editTemplate(template.id)} disabled={busy === "load-template"}>Редактировать</button></div></td>
                </tr>
              ))}</tbody>
            </table>
          </div>
        )}
      </Panel>

      <div className="two-column">
        <Panel title="Назначить график" description="На выбранном отрезке действующий график будет заменён; при пересечении нескольких периодов система попросит уточнить даты.">
          <form className="stack-form" aria-label="Назначить график" onSubmit={assignTemplate}>
            <Field label="Сотрудник"><EmployeeSelect employees={employees} value={employeeId} onChange={setEmployeeId} required /></Field>
            <Field label="График" hint={createdTemplate?.id === templateId ? `${createdTemplate.name}: ${(createdTemplate.weeklyPlannedMinutes / 60).toFixed(1)} ч/нед.` : undefined}>
              <Select value={templateId} onChange={(event) => setTemplateId(event.target.value)} required disabled={templatesLoading}>
                <option value="">{templatesLoading ? "Загружаем графики…" : templates.length === 0 ? "Сначала создайте график" : "Выберите график"}</option>
                {templates.map((template) => <option key={template.id} value={template.id}>{template.name}</option>)}
              </Select>
            </Field>
            <div className="form-grid"><Field label="Действует с"><Input type="date" value={assignmentFrom} onChange={(e) => setAssignmentFrom(e.target.value)} required /></Field><Field label="По"><Input type="date" value={assignmentTo} onChange={(e) => setAssignmentTo(e.target.value)} /></Field></div>
            {(employees.find(employee=>employee.id===employeeId)?.employmentStartDate ?? assignmentFrom) > assignmentFrom && <p className="period-scope-note">Начало графика раньше даты приёма. История занятости будет расширена до начала графика.</p>}
            {assignmentFeedback && <Alert tone={assignmentFeedback.tone} onClose={() => setAssignmentFeedback(null)}>{assignmentFeedback.message}</Alert>}
            <Button type="submit" busy={busy === "assignment"} disabled={Boolean(busy)}>Назначить сотруднику</Button>
          </form>
        </Panel>

        <Panel title="Исключение из графика" description="Выходной, праздник или индивидуальные часы на конкретную дату.">
          <form className="stack-form" aria-label="Исключение из графика" onSubmit={setOverride}>
            <Field label="Сотрудник"><EmployeeSelect employees={employees} value={overrideEmployeeId} onChange={setOverrideEmployeeId} required /></Field>
            <div className="form-grid"><Field label="Дата"><Input type="date" value={overrideDate} onChange={(e) => setOverrideDate(e.target.value)} required /></Field><Field label="Тип"><Select value={overrideType} onChange={(e) => setOverrideType(e.target.value)}><option value="1">Выходной</option><option value="2">Рабочий день</option><option value="3">Особые часы</option><option value="4">Праздник</option><option value="absence">Прогул</option><option value="sick">Больничный</option></Select></Field></div>
            {(overrideType === "2" || overrideType === "3") && <div className="form-grid three"><Field label="Начало"><Input name="startTime" type="time" defaultValue="09:00" required /></Field><Field label="Окончание"><Input name="endTime" type="time" defaultValue="18:00" required /></Field><Field label="Перерыв, мин"><Input name="breakMinutes" type="number" defaultValue={60} min={0} /></Field></div>}
            {overrideType === "sick" && <Field label="Оплата больничного, %"><Input name="paymentPercent" type="number" min={0} max={100} step="0.01" defaultValue={80} required /></Field>}
            <Field label="Причина"><Input name="reason" required maxLength={500} /></Field>
            {(overrideType === "2" || overrideType === "3") && <label className="check-row"><input name="crossesMidnight" type="checkbox" /> Смена заканчивается на следующий день</label>}
            {overrideFeedback && <Alert tone={overrideFeedback.tone} onClose={() => setOverrideFeedback(null)}>{overrideFeedback.message}</Alert>}
            <Button type="submit" busy={busy === "override"} disabled={Boolean(busy)}>Сохранить исключение</Button>
          </form>
        </Panel>
      </div>
    </>
  );
}
