import {useCallback, useEffect, useRef, useState, type FormEvent} from "react";
import {ApiError, apiRequest, errorMessage, jsonBody} from "../api/client";
import {Alert, Button, EmployeeSelect, EmptyState, Field, Input, Loading, Modal, PageHeader, Panel, Select, formatDate, monthBounds} from "../components/ui";
import {useEmployees} from "../hooks/useEmployees";
import {useLiveRefresh} from "../hooks/useLiveRefresh";
import type {EmployeePayRateListItem} from "../types";

interface PayRateInput {
  compensationType:number;
  amount:number;
  currency:string;
  validFrom:string;
  validTo:string;
  overtimeMultiplier:number;
}
interface OverlapWarning { employeeId:string; input:PayRateInput; message:string }

export function PayrollPage() {
  const {employees, error: employeeError} = useEmployees();
  const [employeeId, setEmployeeId] = useState("");
  const [rates, setRates] = useState<EmployeePayRateListItem[]>([]);
  const [type, setType] = useState("2");
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [overlap,setOverlap] = useState<OverlapWarning|null>(null);
  const current = useRef(employeeId); current.current = employeeId;
  const bounds = monthBounds();
  const reload = useCallback(async () => {
    if (!employeeId) {setRates([]); return;}
    setLoading(true);
    try {
      const data = await apiRequest<EmployeePayRateListItem[]>(`/api/employees/${employeeId}/pay-rates`);
      if (current.current === employeeId) setRates(data);
    } catch (e) {if (current.current === employeeId) setError(errorMessage(e));}
    finally {if (current.current === employeeId) setLoading(false);}
  }, [employeeId]);
  useEffect(() => {void reload();}, [reload]);
  useLiveRefresh(reload);
  const submitRate = async (targetEmployeeId:string, input:PayRateInput, replaceExisting=false) => {
    setBusy(true); setError(""); setNotice("");
    try {
      await apiRequest(`/api/employees/${targetEmployeeId}/pay-rates`, {method:"POST", ...jsonBody({...input, replaceExisting})});
      if (current.current !== targetEmployeeId) return;
      setOverlap(null);
      await reload();
      setNotice("Зарплата на выбранный период сохранена. Часы табеля не изменены.");
    } catch (e) {
      if (current.current !== targetEmployeeId) return;
      if (e instanceof ApiError && e.code === "payroll.confirm_rate_replacement") {
        setOverlap({employeeId:targetEmployeeId,input,message:e.message});
      } else {
        const message = e instanceof ApiError && e.code === "payroll.rate_overlap"
          ? "Сервер работает по прежним правилам и запрещает замену зарплаты за пересекающиеся даты. Для сохранения нужно обновить или перезапустить backend CRM. Введённые данные сохранены в форме."
          : errorMessage(e);
        setError(message);
      }
    } finally {setBusy(false);}
  };
  const save = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (!employeeId || busy) return;
    const data = new FormData(event.currentTarget);
    const from = String(data.get("validFrom")), to = String(data.get("validTo"));
    if (from > to) {setError("Дата окончания должна быть не раньше даты начала."); return;}
    await submitRate(employeeId, {
      compensationType:Number(type), amount:Number(data.get("amount")), currency:String(data.get("currency")).toUpperCase(),
      validFrom:from, validTo:to, overtimeMultiplier:Number(data.get("overtimeMultiplier")),
    });
  };
  return <>
    <PageHeader eyebrow="Оплата труда" title="Зарплата" description="Выберите сотрудника и укажите ставку на период. Обе даты включены. Фактическую сумму можно рассчитать в табеле." />
    {(error || employeeError) && <Alert tone="error">{error || employeeError}</Alert>}
    {notice && <Alert tone="success" onClose={() => setNotice("")}>{notice}</Alert>}
    <Panel title="Сотрудник"><Field label="Сотрудник"><EmployeeSelect employees={employees} value={employeeId} disabled={busy} onChange={value => {setOverlap(null); setEmployeeId(value); setRates([]); setNotice(""); setError("");}} /></Field></Panel>
    {!employeeId ? <EmptyState title="Выберите сотрудника" description="Здесь появятся назначенные ставки и форма зарплаты на период." /> : <div className="two-column align-start">
      <Panel title="Назначить зарплату" description="Если даты пересекаются с назначенной зарплатой, покажем периоды и попросим подтвердить замену.">
        <form key={employeeId} className="stack-form" onSubmit={save}>
          <Field label="Тип оплаты"><Select value={type} onChange={e => setType(e.target.value)}><option value="2">Месячный оклад</option><option value="1">Почасовая</option></Select></Field>
          <div className="form-grid"><Field label={type === "2" ? "Месячный оклад" : "Ставка за час"}><Input name="amount" type="number" min={0} step="0.01" required /></Field><Field label="Валюта"><Input name="currency" defaultValue="BYN" pattern="[A-Za-z]{3}" maxLength={3} required /></Field></div>
          <div className="form-grid"><Field label="Действует с"><Input name="validFrom" type="date" defaultValue={bounds.from} required /></Field><Field label="Действует по включительно"><Input name="validTo" type="date" defaultValue={bounds.to} required /></Field></div>
          <Field label="Коэффициент оплаты переработки" hint="1 — обычная ставка, 1,5 — оплата переработки в полуторном размере"><Input name="overtimeMultiplier" type="number" min={1} max={10} step="0.1" defaultValue={1.5} required /></Field>
          <Button type="submit" busy={busy}>Назначить зарплату</Button>
        </form>
      </Panel>
      <Panel title="История зарплаты" description="Оклад — за полный месяц. Фактическая сумма зависит от отработанных часов и ставки на каждый день. После замены ставки за прошлые даты повторный расчёт в табеле покажет новую сумму.">
        {loading ? <Loading /> : rates.length === 0 ? <EmptyState title="Зарплата ещё не назначена" description="Укажите первую ставку и даты её действия." /> : <div className="table-wrap"><table className="salary-history"><thead><tr><th>Период включительно</th><th>Оплата</th><th>Сумма</th><th>Переработка</th></tr></thead><tbody>{rates.map(rate => <tr key={rate.id}><td><strong>{formatDate(rate.validFrom)}</strong><small>по {rate.validTo ? formatDate(rate.validTo) : "без ограничения"}</small></td><td>{rate.compensationType === "Hourly" ? "За час" : "За месяц"}</td><td className="money-cell">{rate.amount.toLocaleString("ru-RU", {minimumFractionDigits:2})} {rate.currency}</td><td>×{rate.overtimeMultiplier}</td></tr>)}</tbody></table></div>}
      </Panel>
    </div>}
    {overlap && <Modal title="Периоды зарплаты пересекаются" onClose={()=>{if(!busy) setOverlap(null);}}>
      <p><strong>{employees.find(employee=>employee.id===overlap.employeeId)?.displayName}</strong></p>
      <div className="day-summary"><span>Новый период: {formatDate(overlap.input.validFrom)} — {formatDate(overlap.input.validTo)} включительно</span><span>Новая зарплата: {overlap.input.amount.toLocaleString("ru-RU")} {overlap.input.currency} {overlap.input.compensationType===1 ? "в час" : "в месяц"}</span></div>
      <Alert tone="warning"><span style={{whiteSpace:"pre-line"}}>{overlap.message}</span></Alert>
      {error && <Alert tone="error">{error}</Alert>}
      <div className="form-actions"><Button variant="ghost" disabled={busy} onClick={()=>{setOverlap(null); setError("");}}>Отмена</Button><Button busy={busy} onClick={()=>void submitRate(overlap.employeeId,overlap.input,true)}>Заменить зарплату</Button></div>
    </Modal>}
  </>;
}
