import { useCallback, useEffect, useState, type FormEvent } from "react";
import { apiRequest, errorMessage, queryString } from "../api/client";
import { Alert, Button, EmptyState, Field, Input, Loading, PageHeader, Panel, formatDateTime } from "../components/ui";
import type { AuditItem, PagedResponse } from "../types";

export function AuditPage() {
  const [filters, setFilters] = useState({ module: "", entityType: "", entityId: "" });
  const [items, setItems] = useState<AuditItem[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const load = useCallback(async () => {
    setLoading(true); setError("");
    try {
      const response = await apiRequest<PagedResponse<AuditItem>>(`/api/audit?${queryString({ ...filters, page, pageSize: 30 })}`);
      setItems(response.items); setTotalCount(response.totalCount);
    } catch (requestError) { setError(errorMessage(requestError)); } finally { setLoading(false); }
  }, [filters, page]);

  useEffect(() => { void load(); }, [load]);

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); const data = new FormData(event.currentTarget);
    setPage(1); setFilters({ module: String(data.get("module") ?? ""), entityType: String(data.get("entityType") ?? ""), entityId: String(data.get("entityId") ?? "") });
  };

  return (
    <>
      <PageHeader eyebrow="Безопасность" title="Журнал аудита" description="Кто, когда и по какой причине изменил бизнес-данные — с correlation ID каждого запроса." />
      {error && <Alert tone="error">{error}</Alert>}
      <Panel>
        <form className="filter-row" onSubmit={submit}>
          <Field label="Модуль"><Input name="module" defaultValue={filters.module} placeholder="Attendance" /></Field>
          <Field label="Тип сущности"><Input name="entityType" defaultValue={filters.entityType} placeholder="TimesheetEntry" /></Field>
          <Field label="ID сущности"><Input name="entityId" defaultValue={filters.entityId} placeholder="UUID или внешний ID" /></Field>
          <Button type="submit">Применить</Button>
        </form>
      </Panel>
      <Panel title={`События · ${totalCount}`} description="Записи неизменяемы из пользовательского интерфейса.">
        {loading ? <Loading /> : items.length === 0 ? <EmptyState title="События не найдены" description="Измените фильтры или выполните бизнес-операцию." /> : <div className="audit-timeline">{items.map((item) => <article key={item.id}><div className="audit-dot" /><div className="audit-card"><header><div><strong>{item.action}</strong><span>{item.module} / {item.entityType}</span></div><time>{formatDateTime(item.timestamp)}</time></header><dl><div><dt>Инициатор</dt><dd>{item.actorUserId}</dd></div><div><dt>Сущность</dt><dd className="mono">{item.entityId}</dd></div>{item.reason && <div><dt>Причина</dt><dd>{item.reason}</dd></div>}<div><dt>Correlation ID</dt><dd className="mono">{item.correlationId}</dd></div></dl></div></article>)}</div>}
        {totalCount > 30 && <div className="pagination"><Button variant="ghost" disabled={page === 1} onClick={() => setPage((value) => value - 1)}>← Назад</Button><span>Страница {page}</span><Button variant="ghost" disabled={page * 30 >= totalCount} onClick={() => setPage((value) => value + 1)}>Вперёд →</Button></div>}
      </Panel>
    </>
  );
}
