import { useMemo, useState, type FormEvent } from "react";
import { apiRequest, errorMessage, jsonBody } from "../api/client";
import { Alert, Badge, Button, EmptyState, Field, Input, Loading, Modal, PageHeader, Panel, Select, formatDate, today } from "../components/ui";
import { useEmployees } from "../hooks/useEmployees";
import type { EmployeeDetails, EmployeeListItem } from "../types";

interface CreateEmployeeForm {
  personnelNumber: string;
  firstName: string;
  lastName: string;
  middleName: string;
  employmentStartDate: string;
  email: string;
  phone: string;
  password: string;
  isStaff: boolean;
  role: "employee" | "company_admin";
}

const initialCreateForm = (): CreateEmployeeForm => ({ personnelNumber: "", firstName: "", lastName: "", middleName: "", employmentStartDate: today(), email: "", phone: "", password: "", isStaff:true, role: "employee" });

export function EmployeesPage() {
  const [search, setSearch] = useState("");
  const { employees, totalCount, loading, error, reload } = useEmployees(search, 100);
  const [showCreate, setShowCreate] = useState(false);
  const [form, setForm] = useState(initialCreateForm);
  const [saving, setSaving] = useState(false);
  const [notice, setNotice] = useState("");
  const [actionError, setActionError] = useState("");
  const [selected, setSelected] = useState<EmployeeDetails | null>(null);
  const [archiveTarget, setArchiveTarget] = useState<EmployeeListItem | null>(null);

  const activeCount = useMemo(() => employees.filter((employee) => employee.status === "Active").length, [employees]);

  const createEmployee = async (event: FormEvent) => {
    event.preventDefault();
    setSaving(true);
    setActionError("");
    try {
      await apiRequest("/api/employees", {
        method: "POST",
        ...jsonBody({
          ...form,
          middleName: form.middleName || null,
          email: form.email || null,
          phone: form.phone || null,
          departmentId: null,
          positionId: null,
          managerId: null,
        }),
      });
      setForm(initialCreateForm());
      setShowCreate(false);
      setNotice("Сотрудник создан в StaffControl и CRM.");
      await reload();
    } catch (requestError) {
      setActionError(errorMessage(requestError));
    } finally {
      setSaving(false);
    }
  };

  const openDetails = async (id: string) => {
    setActionError("");
    try {
      setSelected(await apiRequest<EmployeeDetails>(`/api/employees/${id}`));
    } catch (requestError) {
      setActionError(errorMessage(requestError));
    }
  };

  const archive = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!archiveTarget) return;
    const data = new FormData(event.currentTarget);
    setSaving(true);
    try {
      await apiRequest(`/api/employees/${archiveTarget.id}/archive`, {
        method: "POST",
        ...jsonBody({ employmentEndDate: data.get("date"), reason: data.get("reason") }),
      });
      setArchiveTarget(null);
      setNotice("Сотрудник перемещён в архив.");
      await reload();
    } catch (requestError) {
      setActionError(errorMessage(requestError));
    } finally {
      setSaving(false);
    }
  };

  return (
    <>
      <PageHeader eyebrow="Команда" title="Сотрудники" description="Единый реестр с датами занятости и прозрачным жизненным циклом карточки." actions={<Button onClick={() => setShowCreate(true)}>+ Новый сотрудник</Button>} />
      {notice && <Alert tone="success" onClose={() => setNotice("")}>{notice}</Alert>}
      {(error || actionError) && <Alert tone="error" onClose={() => setActionError("")}>{actionError || error}</Alert>}

      <div className="summary-strip">
        <div><span>Всего</span><strong>{totalCount}</strong></div>
        <div><span>Активны в выборке</span><strong>{activeCount}</strong></div>
        <div><span>Архив</span><strong>{employees.length - activeCount}</strong></div>
      </div>

      <Panel actions={<div className="search-box"><span>⌕</span><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="ФИО или табельный номер" aria-label="Поиск сотрудников" /></div>}>
        {loading ? <Loading /> : employees.length === 0 ? <EmptyState title="Сотрудники не найдены" description="Измените строку поиска или создайте новую карточку." /> : (
          <div className="table-wrap">
            <table>
              <thead><tr><th>Сотрудник</th><th>Табельный №</th><th>Начало работы</th><th>Занятость</th><th>Статус</th><th><span className="sr-only">Действия</span></th></tr></thead>
              <tbody>{employees.map((employee) => (
                <tr key={employee.id}>
                  <td><button className="employee-cell" onClick={() => void openDetails(employee.id)}><span className="person-avatar small">{employee.displayName.split(" ").slice(0, 2).map((part) => part[0]).join("")}</span><strong>{employee.displayName}</strong></button></td>
                  <td className="mono">{employee.personnelNumber}</td>
                  <td>{formatDate(employee.employmentStartDate)}</td>
                  <td><span className="employment-tag">{employee.isStaff === false ? "Внештатный" : "Штатный"}</span></td>
                  <td><Badge value={employee.status} label={employee.status === "Active" ? "Работает" : employee.status === "Archived" ? "В архиве" : employee.status} /></td>
                  <td><div className="row-actions"><button onClick={() => void openDetails(employee.id)}>Открыть</button>{employee.status === "Active" && <button className="danger-link" onClick={() => setArchiveTarget(employee)}>Архив</button>}</div></td>
                </tr>
              ))}</tbody>
            </table>
          </div>
        )}
      </Panel>

      {showCreate && <Modal title="Новый сотрудник" onClose={() => setShowCreate(false)}>
        <form className="form-grid" onSubmit={createEmployee}>
          {actionError && <div className="field-wide"><Alert tone="error">{actionError}</Alert></div>}
          <Field label="Фамилия"><Input value={form.lastName} onChange={(e) => setForm({ ...form, lastName: e.target.value })} required maxLength={100} autoFocus /></Field>
          <Field label="Имя"><Input value={form.firstName} onChange={(e) => setForm({ ...form, firstName: e.target.value })} required maxLength={100} /></Field>
          <Field label="Отчество"><Input value={form.middleName} onChange={(e) => setForm({ ...form, middleName: e.target.value })} maxLength={100} /></Field>
          <Field label="Табельный номер"><Input value={form.personnelNumber} onChange={(e) => setForm({ ...form, personnelNumber: e.target.value })} required maxLength={50} /></Field>
          <Field label="Занятость"><Select value={String(form.isStaff)} onChange={e => setForm({...form, isStaff:e.target.value === "true"})}><option value="true">Штатный</option><option value="false">Внештатный</option></Select></Field>
          <Field label="Дата приёма"><Input type="date" value={form.employmentStartDate} onChange={(e) => setForm({ ...form, employmentStartDate: e.target.value })} required /></Field>
          <Field label="Телефон"><Input type="tel" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} maxLength={50} /></Field>
          <Field label="Email" wide><Input type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} required maxLength={254} /></Field>
          <Field label="Начальный пароль" hint="Не менее 8 символов"><Input type="password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} required minLength={8} autoComplete="new-password" /></Field>
          <Field label="Роль в CRM"><Select value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value as CreateEmployeeForm["role"] })}><option value="employee">Сотрудник</option><option value="company_admin">Администратор компании</option></Select></Field>
          <div className="form-actions field-wide"><Button type="button" variant="ghost" onClick={() => setShowCreate(false)}>Отмена</Button><Button type="submit" busy={saving}>Создать карточку</Button></div>
        </form>
      </Modal>}

      {selected && <Modal title="Карточка сотрудника" onClose={() => setSelected(null)}>
        <div className="profile-card">
          <div className="profile-hero"><div className="person-avatar large">{selected.displayName.split(" ").slice(0, 2).map((part) => part[0]).join("")}</div><div><h3>{selected.displayName}</h3><Badge value={selected.status} label={selected.status === "Active" ? "Работает" : selected.status === "Archived" ? "В архиве" : selected.status} /></div></div>
          <Field label="Занятость"><Select value={String(selected.isStaff !== false)} disabled={saving} onChange={async e => {
            const isStaff=e.target.value === "true"; setSaving(true);
            try {await apiRequest(`/api/employees/${selected.id}/staff-status`, {method:"PUT", ...jsonBody({isStaff})}); setSelected({...selected,isStaff}); await reload();}
            catch (err) {setActionError(errorMessage(err));} finally {setSaving(false);}
          }}><option value="true">Штатный</option><option value="false">Внештатный</option></Select></Field>
          <dl><div><dt>Табельный номер</dt><dd>{selected.personnelNumber}</dd></div><div><dt>Дата приёма</dt><dd>{formatDate(selected.employmentStartDate)}</dd></div><div><dt>Email</dt><dd>{selected.email || "—"}</dd></div><div><dt>Телефон</dt><dd>{selected.phone || "—"}</dd></div></dl>
        </div>
      </Modal>}

      {archiveTarget && <Modal title="Архивировать сотрудника" onClose={() => setArchiveTarget(null)}>
        <form className="form-grid" onSubmit={archive}>
          <div className="field-wide"><Alert tone="warning">{archiveTarget.displayName} останется доступен в исторических табелях и расчётах.</Alert></div>
          <Field label="Последний рабочий день"><Input name="date" type="date" defaultValue={today()} required /></Field>
          <Field label="Причина"><Input name="reason" required minLength={3} maxLength={500} /></Field>
          <div className="form-actions field-wide"><Button type="button" variant="ghost" onClick={() => setArchiveTarget(null)}>Отмена</Button><Button type="submit" variant="danger" busy={saving}>Архивировать</Button></div>
        </form>
      </Modal>}
    </>
  );
}
