export function telegramProblem(code: string): string {
  if (code === "telegram.webhook_configured") return "Этот бот уже подключён к другому сервису. Создайте отдельного бота в BotFather для CRM.";
  if (code === "telegram.bot_already_used") return "Этот бот используется другой компанией в CRM. Для этой компании создайте отдельного бота.";
  if (code === "telegram.bot_not_configured" || code === "notifications.bot_not_configured" || code === "notifications.bot_token_required") return "Вставьте токен от BotFather и нажмите «Сохранить и подключить».";
  if (code === "notifications.channel_not_configured") return "Подключите Telegram выбранного сотрудника во втором шаге, затем повторите отправку.";
  if (code === "telegram.http_401" || code === "telegram.http_404") return "Telegram не принял токен. Скопируйте действующий токен из BotFather целиком и подключите бота снова.";
  if (code === "telegram.http_409") return "Бот запущен ещё в одном приложении. Остановите другое подключение или создайте отдельного бота для CRM.";
  if (code === "telegram.http_429") return "Telegram временно ограничил запросы. Подождите немного и повторите проверку.";
  if (code === "telegram.http_403") return "Telegram запретил отправку. Попросите сотрудника открыть бота и нажать «Старт», затем повторите отправку.";
  return "Не удалось связаться с Telegram. Проверьте доступ сервера CRM к интернету и повторите проверку.";
}

export function telegramError(error: unknown): string {
  if (error instanceof ApiError) {
    if (error.status === 403 && !error.code?.startsWith("telegram.")) return "Для этой настройки нужны права администратора компании.";
    if (error.code?.startsWith("telegram.") || ["notifications.bot_token_required", "notifications.bot_not_configured", "notifications.channel_not_configured"].includes(error.code ?? "")) return telegramProblem(error.code!);
    if (Object.keys(error.validationErrors).some(key => key.toLowerCase().includes("bottoken"))) return "Проверьте токен: скопируйте его из BotFather целиком, без пробелов.";
  }
  return errorMessage(error);
}

export function notificationStatusLabel(status: string): string {
  return ({Queued: "В очереди", Sending: "Отправляется", Delivered: "Доставлено", Failed: "Повторная попытка", DeadLetter: "Не доставлено"} as Record<string, string>)[status] ?? status;
}
