import { useMemo, useState, type FormEvent } from "react";
import { apiRequest, errorMessage, jsonBody } from "../api/client";
import { Alert, Button, EmployeeSelect, EmptyState, Field, Input, PageHeader, Panel, Select, formatDate, monthBounds } from "../components/ui";
import { useEmployees } from "../hooks/useEmployees";
import type { ComparisonResponse } from "../types";

const metrics = [
  { id: 1, key: "PlannedHours", label: "Плановые часы" },
  { id: 2, key: "ActualHours", label: "Фактические часы" },
  { id: 3, key: "OvertimeHours", label: "Сверхурочные" },
  { id: 4, key: "AbsenceHours", label: "Отсутствия" },
];

export function ReportsPage() {
  const { employees, error: employeeError } = useEmployees();
  const bounds = monthBounds();
  const [mode, setMode] = useState("single");
  const [selected, setSelected] = useState<string[]>([]);
  const [dateFrom, setDateFrom] = useState(bounds.from);
  const [dateTo, setDateTo] = useState(bounds.to);
  const [grouping, setGrouping] = useState("3");
  const [selectedMetrics, setSelectedMetrics] = useState<number[]>([1, 2, 3]);
  const [result, setResult] = useState<ComparisonResponse | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const primaryMetric = metrics.find((metric) => selectedMetrics.includes(metric.id)) ?? metrics[0]!;
  const maximum = useMemo(() => Math.max(1, ...(result?.series.map((series) => series.totals[primaryMetric.key] ?? 0) ?? [1])), [primaryMetric.key, result]);

  const toggleEmployee = (id: string) => setSelected((current) => current.includes(id) ? current.filter((item) => item !== id) : current.length < 20 ? [...current, id] : current);
  const toggleMetric = (id: number) => setSelectedMetrics((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]);

  const compare = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try {
      setResult(await apiRequest<ComparisonResponse>("/api/reports/employee-comparison", { method: "POST", ...jsonBody({ employeeIds: selected, dateFrom, dateTo, grouping: Number(grouping), metrics: selectedMetrics, departmentId: null }) }));
    } catch (requestError) { setError(errorMessage(requestError)); } finally { setBusy(false); }
  };

  return (
    <>
      <PageHeader eyebrow="Аналитика" title="Статистика сотрудников" description="Сопоставьте план, фактическое время и отсутствия. Сумму к оплате по актуальным ставкам можно рассчитать в табеле." />
      {(error || employeeError) && <Alert tone="error">{error || employeeError}</Alert>}
      <form onSubmit={compare}>
        <div className={mode === "single" ? "report-single-layout" : "report-layout"}>
          <Panel title="Параметры отчёта" description="Посмотрите статистику одного сотрудника или сравните команду.">
            <div className="stack-form">
              <Field label="Режим отчёта"><Select value={mode} onChange={e => {setMode(e.target.value); setSelected([]); setResult(null);}}><option value="single">Один сотрудник</option><option value="compare">Сравнение сотрудников</option></Select></Field>
              {mode === "single" && <Field label="Сотрудник"><EmployeeSelect employees={employees} value={selected[0] ?? ""} onChange={id => {setSelected(id ? [id] : []); setResult(null);}} /></Field>}
              <div className="form-grid"><Field label="С"><Input type="date" value={dateFrom} onChange={(e) => setDateFrom(e.target.value)} required /></Field><Field label="По"><Input type="date" value={dateTo} onChange={(e) => setDateTo(e.target.value)} required /></Field></div>
              <Field label="Группировка"><Select value={grouping} onChange={(e) => setGrouping(e.target.value)}><option value="1">По дням</option><option value="2">По неделям</option><option value="3">По месяцам</option></Select></Field>
              <div><span className="field-label">Показатели</span><div className="chip-list">{metrics.map((metric) => <label className={selectedMetrics.includes(metric.id) ? "chip selected" : "chip"} key={metric.id}><input type="checkbox" checked={selectedMetrics.includes(metric.id)} onChange={() => toggleMetric(metric.id)} />{metric.label}</label>)}</div></div>
              <Button type="submit" busy={busy} disabled={selected.length < (mode === "single" ? 1 : 2) || selectedMetrics.length === 0}>{mode === "single" ? "Показать статистику" : "Построить сравнение"}</Button>
            </div>
          </Panel>
          {mode === "compare" && <Panel title={`Сотрудники · ${selected.length}`} description="До 20 участников в одном сравнении.">
            <div className="employee-check-list">{employees.map((employee) => <label key={employee.id} className={selected.includes(employee.id) ? "selected" : ""}><input type="checkbox" checked={selected.includes(employee.id)} onChange={() => toggleEmployee(employee.id)} /><span className="person-avatar small">{employee.displayName.split(" ").slice(0, 2).map((part) => part[0]).join("")}</span><span><strong>{employee.displayName}</strong><small>{employee.personnelNumber}</small></span></label>)}</div>
          </Panel>}
        </div>
      </form>

      <Panel title="Результат" description={result ? `${primaryMetric.label}${result.currency ? ` · ${result.currency}` : ""}` : "После построения здесь появится сопоставимая диаграмма."}>
        {!result ? <EmptyState title="Отчёт ещё не построен" description="Выберите сотрудников, период и хотя бы один показатель." /> : result.series.length === 0 ? <EmptyState title="Нет данных" description="В выбранном периоде нет табельных записей." /> : (
          <div className="report-result">
            {result.warnings.length > 0 && <Alert tone="warning">{result.warnings.join(", ")}</Alert>}
            {mode === "single" && result.series[0] && <div className="result-grid statistics-summary">{metrics.filter(metric => selectedMetrics.includes(metric.id)).map(metric => <div key={metric.id}><strong>{(result.series[0]?.totals[metric.key] ?? 0).toLocaleString("ru-RU", {maximumFractionDigits:2})}</strong><span>{metric.label}</span></div>)}</div>}
            <div className="bar-chart">{result.series.map((series) => {
              const value = series.totals[primaryMetric.key] ?? 0;
              return <div className="bar-row" key={series.employeeId}><span>{series.displayName}</span><div><i style={{ width: `${Math.max(2, value / maximum * 100)}%` }} /></div><strong>{value.toLocaleString("ru-RU", { maximumFractionDigits: 2 })}</strong></div>;
            })}</div>
            <div className="table-wrap"><table><thead><tr><th>Сотрудник</th>{metrics.filter((metric) => selectedMetrics.includes(metric.id)).map((metric) => <th key={metric.id}>{metric.label}</th>)}<th>Факт − план</th></tr></thead><tbody>{result.series.map((series) => <tr key={series.employeeId}><td><strong>{series.displayName}</strong></td>{metrics.filter((metric) => selectedMetrics.includes(metric.id)).map((metric) => <td key={metric.id}>{(series.totals[metric.key] ?? 0).toLocaleString("ru-RU", { maximumFractionDigits: 2 })}</td>)}<td className={series.differenceFromPlanned < 0 ? "negative" : "positive"}>{series.differenceFromPlanned.toLocaleString("ru-RU", { maximumFractionDigits: 2 })}</td></tr>)}</tbody></table></div>
            {result.series.map(series => <div key={series.employeeId} className="statistics-detail"><h3>{series.displayName} · динамика за период</h3><div className="table-wrap"><table><thead><tr><th>Период</th>{metrics.filter(metric => selectedMetrics.includes(metric.id)).map(metric => <th key={metric.id}>{metric.label}</th>)}</tr></thead><tbody>{series.points.map(point => <tr key={point.periodLabel}><td><strong>{/^\d{4}-\d{2}-\d{2}$/.test(point.periodLabel) ? formatDate(point.periodLabel) : point.periodLabel}</strong></td>{metrics.filter(metric => selectedMetrics.includes(metric.id)).map(metric => <td key={metric.id}>{(point.values[metric.key] ?? 0).toLocaleString("ru-RU", {maximumFractionDigits:2})}</td>)}</tr>)}</tbody></table></div></div>)}

          </div>
        )}
      </Panel>
    </>
  );
}
