import {useEffect} from "react";
// Re-read when returning to the module after another employee or module changed data.
export function useLiveRefresh(refresh: () => void | Promise<unknown>) {
    useEffect(() => {
        const reload = () => {if (document.visibilityState !== "hidden") void refresh();};
        window.addEventListener("focus", reload); window.addEventListener("online", reload);
        return () => {window.removeEventListener("focus", reload); window.removeEventListener("online", reload);};
    }, [refresh]);
}
