import {useCallback, useEffect, useState} from 'react';
import {getActiveFirmId} from '../api/config';
import {telegramRequest, body} from './api';
import TelegramLinkPanel from './TelegramLinkPanel';
import {Alert, Badge, Button, Field, Input, PageHeader, Panel, Select} from '../staffControl/components/ui';
import {NotificationsPage as StaffNotificationsPage} from '../staffControl/pages/NotificationsPage';
import type {TelegramBotSettings} from '../staffControl/types';

type Connection = {companyId: number | null; companyName: string | null; companyEnabled: boolean;
  isConnected: boolean; transportConnected: boolean; botUsername: string | null; canManage: boolean; sharedBot: boolean};

export default function TelegramSettingsPage({isSuperAdmin}: {isSuperAdmin: boolean}) {
  const [connection, setConnection] = useState<Connection | null>(null);
  const [settings, setSettings] = useState<TelegramBotSettings | null>(null);
  const [token, setToken] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [revision, setRevision] = useState(0);
  const [advanced, setAdvanced] = useState(false);
  const [firm, setFirm] = useState(getActiveFirmId());
  const [companies, setCompanies] = useState<{id: number; name: string}[]>([]);
  const load = useCallback(async (signal?: AbortSignal) => {
    const [current, botSettings] = await Promise.all([
      telegramRequest<Connection>(`/connection${firm ? `?firmId=${encodeURIComponent(firm)}` : ''}`, {signal}),
      isSuperAdmin ? telegramRequest<TelegramBotSettings>('/bot/settings', {signal}) : Promise.resolve(null),
    ]);
    if (!signal?.aborted) {setConnection(current); setSettings(botSettings);}
  }, [isSuperAdmin, firm]);
  useEffect(() => {
    const controller = new AbortController(); setConnection(null); setError('');
    void load(controller.signal).catch(e => {if (!controller.signal.aborted) setError(e.message);});
    return () => controller.abort();
  }, [load]);
  useEffect(() => {
    if (!isSuperAdmin) return;
    const controller = new AbortController();
    void telegramRequest<{id: number; name: string}[]>('/connection/companies', {signal: controller.signal})
      .then(items => {if (!controller.signal.aborted) setCompanies(items);})
      .catch(e => {if (!controller.signal.aborted) setError(e.message);});
    return () => controller.abort();
  }, [isSuperAdmin]);

  async function configureBot(enabled: boolean) {
    setBusy(true); setError(''); setNotice('');
    try {
      if (enabled && !settings?.hasBotToken && !token.trim()) throw new Error('Введите токен бота для первого подключения.');
      await telegramRequest('/bot/settings', body('PUT', {enabled, botToken: token.trim() || null}));
      setToken('');
      if (enabled) await telegramRequest('/bot/connect', {method: 'POST'});
      await load(); setRevision(x => x + 1);
      setNotice(enabled ? 'Общий бот подключён. Теперь пользователи могут подключить свои профили.' : 'Общий бот приостановлен для всех компаний.');
    } catch (e) {setError((e as Error).message);} finally {setBusy(false);}
  }
  async function setCompany(enabled: boolean) {
    if (!connection?.companyId) return;
    setBusy(true); setError(''); setNotice('');
    try {
      await telegramRequest(`/companies/${connection.companyId}/connection`, body('PUT', {enabled}));
      await load(); setRevision(x => x + 1);
      setNotice(enabled ? 'Компания подключена к общему боту.' : 'Компания отключена. Общий бот продолжает работать для остальных компаний.');
    } catch (e) {setError((e as Error).message);} finally {setBusy(false);}
  }
  return <div className="telegram-page">
    <PageHeader eyebrow="Связь с CRM" title="Telegram" description="Подключение компании и ваш личный профиль — в одном месте." />
    {error && <Alert tone="error">{error}</Alert>}
    {notice && <Alert tone="success">{notice}</Alert>}
    {isSuperAdmin && <Field label="Компания"><Select value={firm} disabled={busy} onChange={e => {setFirm(e.target.value); setNotice('');}}>
      <option value="">Общий бот CRM</option>{companies.map(company => <option key={company.id} value={company.id}>{company.name}</option>)}
    </Select></Field>}
    <Panel title={connection?.companyName || 'Бот CRM'} description={connection?.companyName ? 'Подключением компании управляет глобальный администратор.' : 'Один общий бот для CRM.'}
      actions={<Badge value={connection?.isConnected ? 'active' : 'pending'} label={connection ? connection.isConnected ? 'Подключена' : 'Не подключена' : 'Проверяем…'} />}>
      {connection && <div className="stack-form">
        <strong>{connection.isConnected ? connection.companyName ? 'Компания подключена' : 'Бот CRM подключён' : !connection.companyEnabled ? 'Компания отключена от Telegram' : 'Общий бот ещё не подключён'}</strong>
        {connection.botUsername && <span>@{connection.botUsername}</span>}
        {!isSuperAdmin && <p>{connection.isConnected ? 'Подключите только свой профиль кнопкой ниже. Настройки бота уже выполнены.' : 'Обратитесь к глобальному администратору CRM для подключения компании.'}</p>}
        {isSuperAdmin && connection.canManage && connection.companyId && <Button disabled={busy || (!connection.companyEnabled && !connection.transportConnected)} onClick={() => void setCompany(!connection.companyEnabled)}>
          {connection.companyEnabled ? 'Отключить компанию' : 'Подключить компанию'}
        </Button>}
      </div>}
    </Panel>
    <TelegramLinkPanel key={revision} showCompanyStatus={false}/>
    {isSuperAdmin && connection?.canManage && <Panel title="Общий бот CRM" description="Эти настройки доступны только глобальному администратору и действуют для всех компаний.">
      <div className="stack-form">
        <p>{connection.transportConnected ? `Бот @${connection.botUsername} подключён. Повторно вводить токен не нужно.` : settings?.hasBotToken ? 'Токен сохранён. Подключите бота одной кнопкой.' : 'Для первого подключения сохраните токен, выданный BotFather.'}</p>
        {settings?.hasBotToken && !connection.transportConnected && <Button disabled={busy} onClick={() => void configureBot(true)}>Подключить общего бота</Button>}
        <details className="telegram-help" open={settings !== null && !settings.hasBotToken}>
          <summary>{settings?.hasBotToken ? 'Заменить токен общего бота' : 'Настроить токен общего бота'}</summary>
          <div className="stack-form">
            <Field label="Токен общего бота" hint="Получите токен у @BotFather. Сотрудникам и администраторам компаний токен не нужен.">
              <Input type="password" autoComplete="new-password" value={token} maxLength={256} onChange={e => setToken(e.target.value)} disabled={busy}/>
            </Field>
            <Button disabled={busy || !token.trim()} onClick={() => void configureBot(true)}>Сохранить и подключить</Button>
          </div>
        </details>
        {connection.transportConnected && <Button variant="ghost" disabled={busy} onClick={() => void configureBot(false)}>Приостановить общего бота для всех компаний</Button>}
      </div>
    </Panel>}
    {isSuperAdmin && <details className="telegram-help" onToggle={e => setAdvanced(e.currentTarget.open)}>
      <summary>Дополнительные кадровые уведомления</summary>
      {advanced && <StaffNotificationsPage/>}
    </details>}
  </div>;
}
