import type { AppSettings, ProblemDetails } from "../types";
import { STAFF_CONTROL_API_BASE_URL, getAccessToken, getActiveFirmId } from "../../api/config";

const settingsKey = "staffcontrol.settings";

export class ApiError extends Error {
  readonly status: number;
  readonly code?: string;
  readonly traceId?: string;
  readonly validationErrors: Record<string, string[]>;

  constructor(problem: ProblemDetails, status: number) {
    super(problem.detail ?? problem.title ?? `HTTP ${status}`);
    this.name = "ApiError";
    this.status = status;
    this.code = problem.code;
    this.traceId = problem.traceId;
    this.validationErrors = problem.errors ?? {};
  }
}

export const settingsStore = {
  load(): AppSettings {
    const firmId = Number(getActiveFirmId());
    const fallback: AppSettings = {
      accessToken: getAccessToken() ?? "",
      developmentUser: "crm-user",
      activeFirmId: Number.isInteger(firmId) && firmId > 0 ? firmId : null,
    };
    try {
      const stored = localStorage.getItem(settingsKey);
      const parsed = stored ? (JSON.parse(stored) as Partial<AppSettings>) : {};

      // Authentication and company context belong to the host CRM. Never let
      // stale standalone StaffControl settings override the active CRM session.
      return {
        ...fallback,
        developmentUser: parsed.developmentUser || fallback.developmentUser,
      };
    } catch {
      return fallback;
    }
  },
  save(settings: AppSettings) {
    localStorage.setItem(settingsKey, JSON.stringify(settings));
    window.dispatchEvent(new Event("staffcontrol:settings"));
  },
};

export async function apiRequest<T>(path: string, init: RequestInit = {}): Promise<T> {
  const settings = settingsStore.load();
  const headers = new Headers(init.headers);
  headers.set("Accept", "application/json");
  headers.set("X-Dev-User", settings.developmentUser);
  if (settings.accessToken) headers.set("Authorization", `Bearer ${settings.accessToken}`);
  if (settings.activeFirmId) headers.set("X-Firm-Id", String(settings.activeFirmId));
  if (init.body && !(init.body instanceof FormData)) headers.set("Content-Type", "application/json");

  const controller = new AbortController();
  const abort = () => controller.abort();
  init.signal?.addEventListener("abort", abort, {once: true});
  if (init.signal?.aborted) controller.abort();
  let timedOut = false;
  const timer = setTimeout(() => {timedOut = true; controller.abort();}, 60_000);
  try {
    const response = await fetch(`${STAFF_CONTROL_API_BASE_URL}${path}`, { ...init, headers, signal: controller.signal });
    if (!response.ok) {
      let problem: ProblemDetails = { title: response.statusText, status: response.status };
      try {
        problem = (await response.json()) as ProblemDetails;
      } catch {
        // The fallback above remains useful for proxy/network errors without a JSON body.
      }
      throw new ApiError(problem, response.status);
    }

    if (response.status === 204) return undefined as T;
    const text = await response.text();
    if (!text) return undefined as T;

    const contentType = response.headers.get("Content-Type") || "";
    return contentType.includes("json") ? (JSON.parse(text) as T) : (text as T);
  } catch (error) {
    if (timedOut) throw new Error("Время ожидания ответа истекло. Проверьте результат операции перед повторной отправкой.");
    if (error instanceof TypeError) throw new Error("Ответ сервера не получен. Проверьте соединение и результат операции перед повторной отправкой.");
    if (error instanceof SyntaxError) throw new Error("Не удалось прочитать ответ сервера. Обновите данные, чтобы проверить результат операции.");
    throw error;
  } finally {
    clearTimeout(timer);
    init.signal?.removeEventListener("abort", abort);
  }
}

export function jsonBody(value: unknown): Pick<RequestInit, "body"> {
  return { body: JSON.stringify(value) };
}

export function errorMessage(error: unknown): string {
  if (error instanceof ApiError) {
    const validation = Object.values(error.validationErrors).flat().join(" ");
    return [error.message, validation, error.code ? `Код: ${error.code}` : ""].filter(Boolean).join(" · ");
  }
  return error instanceof Error ? error.message : "Неизвестная ошибка";
}

export function queryString(values: Record<string, string | number | boolean | null | undefined>): string {
  const params = new URLSearchParams();
  Object.entries(values).forEach(([key, value]) => {
    if (value !== undefined && value !== null && value !== "") params.set(key, String(value));
  });
  return params.toString();
}
