import React, {useEffect, useState} from "react";
import {AuthUser} from "../models/auth";
import {AppShell, RouteKey} from "./components/AppShell";
import {AttendancePage} from "./pages/AttendancePage";
import {AuditPage} from "./pages/AuditPage";
import {DashboardPage} from "./pages/DashboardPage";
import {EmployeesPage} from "./pages/EmployeesPage";
import TelegramSettingsPage from "../telegram/TelegramSettingsPage";
import {PayrollPage} from "./pages/PayrollPage";
import {ReportsPage} from "./pages/ReportsPage";
import {SchedulesPage} from "./pages/SchedulesPage";

const routes = new Set<RouteKey>(["dashboard", "employees", "schedules", "attendance", "payroll", "reports", "notifications", "audit"]);

const routeFromHash = (): RouteKey => {
    const value = window.location.hash.replace(/^#\/staff\/?/, "") as RouteKey;
    return routes.has(value) ? value : "dashboard";
};

interface Props {
    user: AuthUser;
    onSignOut: () => void;
}

const StaffControlApp = ({user, onSignOut}: Props) => {
    const [route, setRoute] = useState<RouteKey>(routeFromHash);

    useEffect(() => {
        const listener = () => setRoute(routeFromHash());
        window.addEventListener("hashchange", listener);
        return () => window.removeEventListener("hashchange", listener);
    }, []);

    const navigate = (target: RouteKey) => {
        window.location.hash = `/staff/${target}`;
        setRoute(target);
    };

    const pages: Record<RouteKey, React.ReactNode> = {
        dashboard: <DashboardPage onNavigate={navigate}/>,
        employees: <EmployeesPage/>,
        schedules: <SchedulesPage/>,
        attendance: <AttendancePage/>,
        payroll: <PayrollPage/>,
        reports: <ReportsPage/>,
        notifications: <TelegramSettingsPage isSuperAdmin={user.role === 'super_admin'}/>,
        audit: <AuditPage/>,
    };

    return (
        <AppShell route={route} onNavigate={navigate} user={user} onSignOut={onSignOut}>
            {pages[route]}
        </AppShell>
    );
};

export default StaffControlApp;
