import {useCallback, useEffect, useState} from 'react';
import {telegramRequest} from './api';
import './telegram.css';

type LinkState = {telegramUserId: number | null; telegramLinkedAt: string | null; botConnected?: boolean;
  companyEnabled?: boolean; companyName?: string | null; botUsername?: string | null; isLinked?: boolean};
type Ticket = {code: string; deepLink: string; expiresAt: string};

export default function TelegramLinkPanel({showCompanyStatus = true}: {showCompanyStatus?: boolean}) {
  const [link, setLink] = useState<LinkState | null>(null);
  const [ticket, setTicket] = useState<Ticket | null>(null);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const [now, setNow] = useState(Date.now());
  const load = useCallback(async () => {
    const current = await telegramRequest<LinkState>('/link');
    setLink(current);
    if (current.isLinked ?? current.telegramUserId) setTicket(null);
  }, []);
  useEffect(() => {void load().catch(e => setError(e.message));}, [load]);
  useEffect(() => {
    if (!ticket) return;
    const timer = window.setInterval(() => {
      setNow(Date.now());
      if (Date.now() < Date.parse(ticket.expiresAt)) void load().catch(e => setError(e.message));
    }, 5000);
    return () => window.clearInterval(timer);
  }, [ticket, load]);
  async function act(unlink: boolean) {
    if (!unlink && ticket && Date.parse(ticket.expiresAt) > Date.now()) {
      window.open(ticket.deepLink, '_blank', 'noopener,noreferrer'); return;
    }
    // Open within the click gesture so mobile browsers do not block the Telegram transition.
    const popup = !unlink ? window.open('about:blank', '_blank') : null;
    if (popup) popup.opener = null;
    setError(''); setBusy(true);
    try {
      if (unlink) {await telegramRequest('/link', {method: 'DELETE'}); setTicket(null); await load();}
      else {
        const next = await telegramRequest<Ticket>('/link', {method: 'POST'});
        const url = new URL(next.deepLink);
        if (url.protocol !== 'https:' || url.hostname !== 't.me' || url.username || url.password) throw new Error('Не удалось открыть ссылку Telegram. Повторите подключение.');
        setTicket(next); setNow(Date.now());
        if (popup) popup.location.replace(next.deepLink);
      }
    } catch (e) {popup?.close(); setError((e as Error).message);} finally {setBusy(false);}
  }
  const expired = ticket && Date.parse(ticket.expiresAt) <= now;
  return <section className="tg-panel" aria-label="Личный Telegram">
    <h1>Мой Telegram</h1>
    <p>Нажмите «Подключить Telegram», затем «Старт» в боте. Профиль привяжется автоматически.</p>
    <p>Чтобы добавить накладную в CRM, отправьте подключённому боту PDF или фотографию до 20 МБ.
      Нажмите в боте «Загрузить файл для прихода». При необходимости выберите компанию кнопкой по её названию.
      После распознавания проверьте документ в разделе «Файлы для прихода» и подтвердите приход.</p>
    {showCompanyStatus && link && <div className="tg-link-state" role="status">
      <strong>{link.companyEnabled === false ? 'Telegram компании отключён' : link.botConnected === false ? 'Бот ещё не настроен' : link.companyName ? 'Компания подключена' : 'Бот CRM подключён'}</strong>
      {link.companyName && <span>{link.companyName}</span>}
      {link.botUsername && <span>@{link.botUsername}</span>}
    </div>}
    {(link?.companyEnabled === false || link?.botConnected === false) && <p>Подключение компании настраивает глобальный администратор. После включения вы сможете подключить свой профиль здесь.</p>}
    <p><a href={`${window.location.pathname}?telegramPreview=1`}>Открыть мини-приложение в браузере →</a></p>
    {error && <p role="alert">{error}</p>}
    {link?.telegramUserId ? <>
      <p role="status">Ваш профиль Telegram подключён{link.telegramLinkedAt && ` · ${new Date(link.telegramLinkedAt).toLocaleString()}`}.</p>
      {link.botUsername && <p><a href={`https://t.me/${encodeURIComponent(link.botUsername)}?start=menu`} target="_blank" rel="noopener noreferrer">Открыть бота с кнопками →</a></p>}
      <button disabled={busy} onClick={() => void act(true)}>Отозвать привязку и доступ WebApp</button>
    </> : <button disabled={busy || !link || link.companyEnabled === false || link.botConnected === false} onClick={() => void act(false)}>Подключить Telegram</button>}
    {ticket && <div>
      {expired ? <p>Ссылка истекла. Создайте новую.</p> : <>
        <p>Telegram открыт. Нажмите «Старт» в боте — здесь появится подтверждение подключения.</p>
        <p><a href={ticket.deepLink} target="_blank" rel="noreferrer">Открыть бота и подключить</a></p>
        <p>Если Telegram не открылся, используйте ссылку выше. Она действует до {new Date(ticket.expiresAt).toLocaleTimeString()}.</p>
      </>}
    </div>}
  </section>;
}
