import { useCallback, useEffect, useState } from "react";
import { apiRequest, errorMessage, queryString } from "../api/client";
import type { EmployeeListItem, PagedResponse } from "../types";

export function useEmployees(search = "", pageSize = 100) {
  const [employees, setEmployees] = useState<EmployeeListItem[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  const reload = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      let synchronizationError = "";
      try {
        await apiRequest("/api/integration/employees/sync", { method: "POST" });
      } catch (requestError) {
        synchronizationError = `Синхронизация с CRM: ${errorMessage(requestError)}`;
      }
      const query = queryString({ search, page: 1, pageSize });
      const response = await apiRequest<PagedResponse<EmployeeListItem>>(`/api/employees?${query}`);
      setEmployees(response.items);
      setTotalCount(response.totalCount);
      setError(synchronizationError);
    } catch (requestError) {
      setError(errorMessage(requestError));
    } finally {
      setLoading(false);
    }
  }, [pageSize, search]);

  useEffect(() => {
    void reload();
  }, [reload]);

  return { employees, totalCount, loading, error, reload };
}
