import type { ButtonHTMLAttributes, InputHTMLAttributes, ReactNode, SelectHTMLAttributes, TextareaHTMLAttributes } from "react";
import {useEffect, useRef} from "react";
import type { EmployeeListItem } from "../types";

export function PageHeader({ eyebrow, title, description, actions }: { eyebrow?: string; title: string; description: string; actions?: ReactNode }) {
  return (
    <header className="page-header">
      <div>
        {eyebrow && <div className="eyebrow">{eyebrow}</div>}
        <h1>{title}</h1>
        <p>{description}</p>
      </div>
      {actions && <div className="page-actions">{actions}</div>}
    </header>
  );
}

export function Panel({ title, description, actions, children, className = "" }: { title?: string; description?: string; actions?: ReactNode; children: ReactNode; className?: string }) {
  return (
    <section className={`panel ${className}`}>
      {(title || description || actions) && (
        <div className="panel-heading">
          <div>
            {title && <h2>{title}</h2>}
            {description && <p>{description}</p>}
          </div>
          {actions}
        </div>
      )}
      {children}
    </section>
  );
}

export function Field({ label, hint, children, wide = false }: { label: string; hint?: string; children: ReactNode; wide?: boolean }) {
  return (
    <label className={`field ${wide ? "field-wide" : ""}`}>
      <span>{label}</span>
      {children}
      {hint && <small>{hint}</small>}
    </label>
  );
}

export function Input(props: InputHTMLAttributes<HTMLInputElement>) {
  return <input {...props} />;
}

export function Select(props: SelectHTMLAttributes<HTMLSelectElement>) {
  return <select {...props} />;
}

export function Textarea(props: TextareaHTMLAttributes<HTMLTextAreaElement>) {
  return <textarea {...props} />;
}

export function Button({ variant = "primary", busy, children, ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: "primary" | "secondary" | "ghost" | "danger"; busy?: boolean }) {
  return (
    <button {...props} className={`button button-${variant} ${props.className ?? ""}`} disabled={props.disabled || busy}>
      {busy && <span className="spinner spinner-small" aria-hidden="true" />}
      {children}
    </button>
  );
}

export function Alert({ tone = "info", children, onClose }: { tone?: "info" | "success" | "error" | "warning"; children: ReactNode; onClose?: () => void }) {
  return (
    <div className={`alert alert-${tone}`} role={tone === "error" ? "alert" : "status"}>
      <span>{children}</span>
      {onClose && <button type="button" onClick={onClose} aria-label="Закрыть">×</button>}
    </div>
  );
}

export function Badge({ value, label }: { value: string; label?: string }) {
  const normalized = value.toLowerCase();
  const tone = normalized.includes("active") || normalized.includes("approved") || normalized.includes("delivered") || normalized.includes("complete")
    ? "success"
    : normalized.includes("error") || normalized.includes("failed") || normalized.includes("dead") || normalized.includes("archive")
      ? "danger"
      : normalized.includes("pending") || normalized.includes("open") || normalized.includes("planned")
        ? "warning"
        : "neutral";
  return <span className={`badge badge-${tone}`}>{label ?? value}</span>;
}

export function Loading({ label = "Загружаем данные" }: { label?: string }) {
  return <div className="loading"><span className="spinner" />{label}</div>;
}

export function EmptyState({ title, description }: { title: string; description: string }) {
  return <div className="empty-state"><div className="empty-mark">SC</div><h3>{title}</h3><p>{description}</p></div>;
}

export function EmployeeSelect({ employees, value, onChange, required = false, includeEmpty = true, disabled = false }: { employees: EmployeeListItem[]; value: string; onChange: (value: string) => void; required?: boolean; includeEmpty?: boolean; disabled?: boolean }) {
  return (
    <Select value={value} onChange={(event) => onChange(event.target.value)} required={required} disabled={disabled}>
      {includeEmpty && <option value="">Выберите сотрудника</option>}
      {employees.map((employee) => <option key={employee.id} value={employee.id}>{employee.displayName} · {employee.personnelNumber}</option>)}
    </Select>
  );
}

export function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  const dialogRef = useRef<HTMLElement>(null);
  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;
    const root = dialog.getRootNode() as Document | ShadowRoot;
    const previous = root.activeElement as HTMLElement | null;
    const overflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    dialog.querySelector<HTMLElement>('button, input, select, textarea, [tabindex="0"]')?.focus();
    return () => {document.body.style.overflow = overflow; if (previous?.isConnected) previous.focus();};
  }, []);
  return (
    <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.currentTarget === event.target) onClose(); }}>
      <section ref={dialogRef} className="modal" role="dialog" aria-modal="true" aria-label={title} tabIndex={-1} onKeyDown={event => {
        if (event.key === "Escape") {event.stopPropagation(); onClose();}
        if (event.key !== "Tab") return;
        const controls = Array.from(dialogRef.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), a[href], [tabindex="0"]') || []).filter(item => item.getClientRects().length > 0);
        const first = controls[0], last = controls[controls.length - 1];
        if (!first) {event.preventDefault(); dialogRef.current?.focus();}
        else if (event.shiftKey && (event.target === first || event.target === dialogRef.current)) {event.preventDefault(); last.focus();}
        else if (!event.shiftKey && event.target === last) {event.preventDefault(); first.focus();}
      }}>
        <header><h2>{title}</h2><button type="button" onClick={onClose} aria-label="Закрыть">×</button></header>
        {children}
      </section>
    </div>
  );
}

export function MetricCard({ label, value, caption, accent = "mint" }: { label: string; value: ReactNode; caption: string; accent?: "mint" | "amber" | "blue" | "rose" }) {
  const isTextValue = typeof value === "string" && /[a-zа-яё]/i.test(value);
  return <article className={`metric-card metric-${accent}${isTextValue ? " metric-text" : ""}`}><span>{label}</span><strong>{value}</strong><small>{caption}</small></article>;
}

export function formatDate(value?: string | null): string {
  if (!value) return "—";
  return new Intl.DateTimeFormat("ru-RU").format(new Date(`${value}T00:00:00`));
}

export function formatDateTime(value?: string | null): string {
  if (!value) return "—";
  return new Intl.DateTimeFormat("ru-RU", { dateStyle: "short", timeStyle: "short" }).format(new Date(value));
}

export function minutesToHours(value?: number | null): string {
  if (value === null || value === undefined) return "—";
  return `${(value / 60).toLocaleString("ru-RU", { maximumFractionDigits: 1 })} ч`;
}

export function today(): string {
  const date = new Date();
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}

export function monthBounds(date = new Date()): { from: string; to: string } {
  const from = new Date(date.getFullYear(), date.getMonth(), 1);
  const to = new Date(date.getFullYear(), date.getMonth() + 1, 0);
  const local = (item: Date) => `${item.getFullYear()}-${String(item.getMonth() + 1).padStart(2, "0")}-${String(item.getDate()).padStart(2, "0")}`;
  return { from: local(from), to: local(to) };
}
