import { useEffect, useState } from "react";
import { apiRequest } from "../api/client";
import type { RouteKey } from "../components/AppShell";
import { Alert, Badge, EmptyState, Loading, MetricCard, PageHeader, Panel, formatDate } from "../components/ui";
import { useEmployees } from "../hooks/useEmployees";

export function DashboardPage({ onNavigate }: { onNavigate: (route: RouteKey) => void }) {
  const { employees, totalCount, loading, error } = useEmployees("", 8);
  const [apiOnline, setApiOnline] = useState<boolean | null>(null);

  useEffect(() => {
    apiRequest<unknown>("/health/live").then(() => setApiOnline(true)).catch(() => setApiOnline(false));
  }, []);

  const active = employees.filter((employee) => employee.status === "Active").length;
  const todayLabel = new Intl.DateTimeFormat("ru-RU", { weekday: "long", day: "numeric", month: "long" }).format(new Date());

  return (
    <>
      <PageHeader eyebrow={todayLabel} title="Обзор команды" description="Люди, рабочее время и зарплата. Всё важное для вашего дня." actions={<button className="button button-primary" onClick={() => onNavigate("employees")}>Открыть сотрудников</button>} />
      {error && <Alert tone="error">Не удалось загрузить данные: {error}</Alert>}
      <div className="metric-grid">
        <MetricCard label="Сотрудники" value={loading ? "…" : totalCount} caption="в общей базе" accent="mint" />
        <MetricCard label="Активны" value={loading ? "…" : active} caption="в текущей выборке" accent="blue" />
        <MetricCard label="Соединение" value={apiOnline === null ? "…" : apiOnline ? "Доступно" : "Нет связи"} caption="сервис персонала" accent={apiOnline ? "mint" : "rose"} />
        <MetricCard label="Период" value={new Intl.DateTimeFormat("ru-RU", { month: "short" }).format(new Date())} caption="операционный месяц" accent="amber" />
      </div>

      <div className="dashboard-grid">
        <Panel title="Последние сотрудники" description="Быстрый срез реестра" actions={<button className="link-button" onClick={() => onNavigate("employees")}>Открыть реестр →</button>}>
          {loading ? <Loading /> : employees.length === 0 ? <EmptyState title="В базе пока пусто" description="Создайте первого сотрудника, затем назначьте ему график." /> : (
            <div className="people-list">
              {employees.slice(0, 6).map((employee) => (
                <div className="person-row" key={employee.id}>
                  <div className="person-avatar">{employee.displayName.split(" ").slice(0, 2).map((part) => part[0]).join("")}</div>
                  <div><strong>{employee.displayName}</strong><span>№ {employee.personnelNumber} · с {formatDate(employee.employmentStartDate)}</span></div>
                  <Badge value={employee.status} label={employee.status === "Active" ? "Работает" : employee.status === "Archived" ? "В архиве" : employee.status} />
                </div>
              ))}
            </div>
          )}
        </Panel>

        <Panel title="Рабочий контур" description="Рекомендуемая последовательность настройки" className="workflow-panel">
          <ol className="workflow-list">
            <li><button onClick={() => onNavigate("employees")}><span>01</span><div><strong>Команда</strong><small>Создайте карточки сотрудников</small></div></button></li>
            <li><button onClick={() => onNavigate("schedules")}><span>02</span><div><strong>Графики</strong><small>Настройте шаблон и назначения</small></div></button></li>
            <li><button onClick={() => onNavigate("attendance")}><span>03</span><div><strong>Табель</strong><small>Сгенерируйте план и внесите факт</small></div></button></li>
            <li><button onClick={() => onNavigate("payroll")}><span>04</span><div><strong>Зарплата</strong><small>Зафиксируйте ставки и период</small></div></button></li>
          </ol>
        </Panel>
      </div>
    </>
  );
}
